        if (c.hierarchy === 'C-Level') return false;                 // 🛡️ C-Level = pipeline potencial
        if (c.hierarchy === 'Director') return false;                // 🛡️ Director = influencia
        if (c.hierarchy === 'Gerente') return false;                 // 🛡️ Gerente = decisor operativo
        if (c.email) return false;                                   // 🛡️ tiene email = dato valioso
