// THEME SWITCHER
// ═══════════════════════════════════════════════════════════════════════
function toggleTheme() {
  const isLight = document.body.classList.toggle('light');
  localStorage.setItem('theme', isLight ? 'light' : 'dark');
  
  const icon = document.getElementById('theme-icon');
  const text = document.getElementById('theme-text');
  if (isLight) {
    icon.textContent = '🌙';
    text.textContent = 'Modo Oscuro';
    if (typeof switchGisTileLayer === 'function') {
      switchGisTileLayer('voyager');
    }
  } else {
    icon.textContent = '☀️';
    text.textContent = 'Modo Claro';
    if (typeof switchGisTileLayer === 'function') {
      switchGisTileLayer('dark');
    }
  }
}

(function() {
  // Forzar Dark Theme por defecto (Slate 950)
  document.body.classList.remove('light');
  localStorage.setItem('theme', 'dark');
})();

document.addEventListener('DOMContentLoaded', () => {
  // Carga automática de los datos enriquecidos y navega directo a Mi Red
  if (typeof loadDemoData === 'function') {
    loadDemoData(true);
  }
});

