function getDisplayName(c, idx) {
  if (!c) return 'Sin nombre';
  const name = c.name || c.full_name || c.originalName || (c.first_name ? (c.first_name + ' ' + (c.last_name || '')).trim() : '') || 'Sin nombre';
  if (!S.isDemoMode) return name;
  const prefix = name !== 'Sin nombre' ? name[0].toUpperCase() : 'X';
  return `Contacto ${prefix}*** (Anonimizado)`;
}

function getDisplayNameHTML(c, idx) {
  const nameText = getDisplayName(c, idx);
  if (!c || S.isDemoMode) {
    return `<span style="font-weight:700;">${nameText}</span>`;
  }
  const href = c.url || `https://www.linkedin.com/search/results/all/?keywords=${encodeURIComponent((c.name || '') + ' ' + (c.company || ''))}`;
  return `<a href="${href}" target="_blank" rel="noopener" class="name-link" style="color:var(--text); text-decoration:none; font-weight:700; transition:color 0.15s ease;" onmouseover="this.style.color='var(--accent)';" onmouseout="this.style.color='var(--text)';" title="Abrir perfil de LinkedIn de ${c.name}">${nameText} <span style="font-size:9px; opacity:0.6;">🔗</span></a>`;
}

