function norm(t) {
  if (!t) return '';
  return t.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9\s]/g,' ').trim();
}

function showToast(msg, icon = '✨') {
  let toast = document.getElementById('ui-toast');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'ui-toast';
    document.body.appendChild(toast);
  }
  toast.innerHTML = `<span style="font-size:16px">${icon}</span><span>${msg}</span>`;
  toast.classList.add('show');
  setTimeout(() => {
    toast.classList.remove('show');
  }, 2800);
}

function copyPitch() {
  const textElem = document.getElementById('modal-pitch-text');
  if (!textElem) return;
  const text = textElem.innerText;
  navigator.clipboard.writeText(text).then(() => {
    showToast('¡Pitch copiado al portapapeles! Listo para enviar en LinkedIn.', '📋');
  }).catch(() => {
    showToast('Copiado al portapapeles', '📋');
  });
}
function inferCountry(email, company, position) {
  const key = `${(company||'').trim()} | ${(position||'').trim()}`;
  if (window.normalizedLocations && window.normalizedLocations[key]) {
      const c = window.normalizedLocations[key].country;
      if (c && c !== 'Desconocido') return c;
  }
  
  const e = (email||'').toLowerCase();
  const b = norm(`${company} ${position}`);

  if (e.endsWith('.mx')) return 'México';
  if (e.endsWith('.cl')) return 'Chile';
  if (e.endsWith('.co')) return 'Colombia';
  if (e.endsWith('.pe')) return 'Perú';
  if (e.endsWith('.br')) return 'Brasil';
  if (e.endsWith('.ar')) return 'Argentina';
  if (e.endsWith('.es')) return 'España';
  if (e.endsWith('.ec')) return 'Ecuador';
  if (e.endsWith('.uy')) return 'Uruguay';
  if (e.endsWith('.cr')) return 'Costa Rica';

  if (/\b(mexico|cdmx|monterrey|guadalajara|cancun|queretaro|puebla|tijuana|merida|leon|toluca|zapopan|san luis potosi|aguascalientes|hermosillo|veracruz|mx)\b/.test(b)) return 'México';
  if (/\b(chile|santiago|valparaiso|concepcion|antofagasta|temuco|cl)\b/.test(b)) return 'Chile';
  if (/\b(colombia|bogota|medellin|cali|barranquilla|cartagena|bucaramanga|co)\b/.test(b)) return 'Colombia';
  if (/\b(peru|lima|arequipa|trujillo|cusco|pe)\b/.test(b)) return 'Perú';
  if (/\b(brasil|brazil|sao paulo|rio de janeiro|curitiba|belo horizonte|porto alegre|br)\b/.test(b)) return 'Brasil';
  if (/\b(argentina|buenos aires|cordoba|rosario|mendoza|la plata|ar)\b/.test(b)) return 'Argentina';
  if (/\b(espana|spain|madrid|barcelona|valencia|sevilla|bilbao|malaga|es)\b/.test(b)) return 'España';
  if (/\b(usa|united states|new york|san francisco|chicago|houston|miami|austin|seattle|boston|los angeles|us)\b/.test(b)) return 'USA';
  if (/\b(equador|ecuador|quito|guayaquil|cuenca)\b/.test(b)) return 'Ecuador';
  if (/\b(uruguay|montevideo)\b/.test(b)) return 'Uruguay';
  if (/\b(costa rica|san jose)\b/.test(b)) return 'Costa Rica';

  return 'Desconocido';
}

function inferHierarchy(pos) {
  const p = norm(pos);
  if (/\b(ceo|cfo|cto|cmo|cro|coo|founder|fundador|cofounder|director general|managing director|presidente)\b/.test(p)) return 'C-Level';
  if (/\b(director|head|vp|vice president|vicepresidente)\b/.test(p)) return 'Director';
  if (/\b(gerente|manager|jefe|responsable|lead)\b/.test(p)) return 'Gerente';
  return 'Otros';
}

function inferSector(pos, company) {
  const b = norm(`${pos} ${company}`);
  if (/\b(fintech|pago|pay|cobro|treasury|tesoreria|banking|bank|banco|credito|credit|adquirente|pos|terminal|finance|financiero|wallet|card|tarjeta|gateway|clip|fiserv|conekta|kueski|konfio|coppel|banamex|bbva|santander|hsbc|visa|mastercard|amex|stripe|paypal|mercadopago|kushki|culqi|wompi|transbank|getnet|cielo|stone|pagseguro|nuvei|openpay|spei|acquiring|issuing|payment)\b/.test(b)) return 'Fintech/Pagos';
  if (/\b(retail|ecommerce|commerce|tienda|store|marketplace|comercio|liverpool|palacio|elektra|walmart|costco)\b/.test(b)) return 'Retail/eCommerce';
  if (/\b(software|saas|tech|platform|developer|engineer|startup|digital|cloud|system|it|ti|tecnologia|technology|cyber|seguridad|security|ai|ia|analytics|data)\b/.test(b)) return 'SaaS/Tech';
  if (/\b(manufactura|industrial|planta|supply|logistic|transport|delivery)\b/.test(b)) return 'Manufactura/Logística';
  if (/\b(health|salud|pharma|hospital|medico|clinica)\b/.test(b)) return 'Salud';
  if (/\b(educacion|universidad|school|edtech|instituto)\b/.test(b)) return 'Educación';
  if (/\b(gobierno|municipal|federal|secretaria|publico)\b/.test(b)) return 'Gobierno';
  if (/\b(consulting|consultor|advisory|strategy|consultoria)\b/.test(b)) return 'Consultoría';
  if (/\b(media|marketing|publicidad|advertising|agencia|agency)\b/.test(b)) return 'Marketing/Media';
  if (/\b(cpg|fmcg|consumo|alimento|food|bebida|drink|beverage|tobacco|tabaco|cigarette|cigarro|dulce|candy|snack|panaderia|bakery|leche|dairy|brand|marca|distribuidora|importadora|cosmetic|belleza|beauty|perfume|soap|shampoo|higiene)\b/.test(b)) return 'Consumo Masivo/CPG';
  return 'Otro';
}


function scoreContact(c) {
  const icpText = norm(document.getElementById('icp-override')?.value || '');
  const activePos = S.positions.length ? S.positions[S.activePositionIndex || 0] : null;
  const ownerSector = activePos ? inferSector(activePos.title, activePos.company) : '';
  let score = 0;
  // Jerarquía
  if (c.hierarchy === 'C-Level') score += 35;
  else if (c.hierarchy === 'Director') score += 20;
  else if (c.hierarchy === 'Gerente') score += 10;
  // Geografía conocida
  if (c.country !== 'Desconocido') score += 15;
  // Sector alineado con el tuyo
  if (c.sector === ownerSector && ownerSector && ownerSector !== 'Otro') score += 25;
  // Datos de contacto
  if (c.email) score += 10;
  // Conexión reciente = más caliente
  if (c.connectedYearsAgo < 2) score += 10;
  if (c.connectedYearsAgo < 1) score += 5;
  // Relación warm: hay historial de DMs
  if (c.msg_count && c.msg_count > 0) score += 15;
  // Sentimiento positivo en DMs = lead caliente confirmado
  if (c.sentiment === '\uD83D\uDFE2 Inter\u00e9s Alto / Dispuesto a Demo') score += 10;
  if (c.intent === 'Lead C\u00e1lido / Oportunidad Real' || c.intent === 'Cualificaci\u00f3n en Proceso') score += 10;
  // ICP override text match
  if (icpText) {
    const blob = norm(`${c.position} ${c.company} ${c.sector} ${c.country}`);
    const words = icpText.split(/\s+/).filter(w => w.length > 3);
    const matches = words.filter(w => blob.includes(w)).length;
    score += Math.round((matches / Math.max(words.length, 1)) * 20);
  }
  return Math.min(100, score);
}

function scoreColor(s) {
  if (s >= 70) return 'var(--green)';
  if (s >= 45) return 'var(--amber)';
  return 'var(--red)';
}

