function connectedYearsAgo(str) {
  if (!str) return 99;
  try {
    // Formato ISO: "2021-07-15" o "2021-07"
    if (/^\d{4}-\d{2}/.test(str.trim())) {
      const d = new Date(str.trim());
      if (!isNaN(d)) return (Date.now() - d) / (365.25 * 86400 * 1000);
    }
    // Formato LinkedIn export: "15 Jul 2021" o "Jul 2021"
    const months = {jan:0,feb:1,mar:2,apr:3,may:4,jun:5,jul:6,aug:7,sep:8,oct:9,nov:10,dec:11};
    const parts = str.trim().split(' ');
    if (parts.length === 3) {
      const d = new Date(parseInt(parts[2]), months[parts[1].toLowerCase().slice(0,3)], parseInt(parts[0]));
      if (!isNaN(d)) return (Date.now() - d) / (365.25 * 86400 * 1000);
    }
    if (parts.length === 2) {
      const monthKey = parts[0].toLowerCase().slice(0,3);
      const year = parseInt(parts[1]);
      if (months[monthKey] !== undefined && !isNaN(year)) {
        const d = new Date(year, months[monthKey], 1);
        return (Date.now() - d) / (365.25 * 86400 * 1000);
      }
    }
    // Último recurso: solo año
    if (/^\d{4}$/.test(str.trim())) {
      const d = new Date(parseInt(str.trim()), 0, 1);
      return (Date.now() - d) / (365.25 * 86400 * 1000);
    }
  } catch(e) {}
  return 99;
}

