// FILE PROCESSING
// ═══════════════════════════════════════════════════════════════════════
document.getElementById('zip-input').addEventListener('change', e => {
  const files = e.target.files;
  if (files && files.length > 0) handleFiles(Array.from(files));
});

const dropZone = document.getElementById('drop-zone');
dropZone.addEventListener('dragover', e => { e.preventDefault(); dropZone.classList.add('drag-over'); });
dropZone.addEventListener('dragleave', () => dropZone.classList.remove('drag-over'));
dropZone.addEventListener('drop', e => {
  e.preventDefault();
  dropZone.classList.remove('drag-over');
  if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
    handleFiles(Array.from(e.dataTransfer.files));
  }
});

async function handleFiles(files) {
  setLoading(true, 10);
  let processedAny = false;
  let errors = [];

  for (let i = 0; i < files.length; i++) {
    const file = files[i];
    const name = file.name.toLowerCase();
    const progress = Math.round(10 + (i / files.length) * 80);
    setLoading(true, progress);

    try {
      if (name.endsWith('.zip')) {
        const zip = await JSZip.loadAsync(file);
        const didProcess = await processZip(zip);
        if (didProcess) processedAny = true;
      } else if (name.endsWith('.csv')) {
        const didProcess = await processCSVOnly(file);
        if (didProcess) processedAny = true;
      } else {
        errors.push(`${file.name}: Formato no soportado.`);
      }
    } catch(err) {
      errors.push(`${file.name}: ${err.message}`);
    }
  }

  if (processedAny) {
    await normalizeWithAPI();
    
    // Save imported data to Supabase
    if (currentUser) {
      setLoading(true, 95);
      console.log("Upserting contacts to Supabase...");
      
      const chunkSize = 200;
      for (let i = 0; i < S.contacts.length; i += chunkSize) {
        const chunk = S.contacts.slice(i, i + chunkSize).map(c => ({
          contact_id: c.url || c.profile_url || String(c.id),
          user_id: currentUser.id,
          first_name: c.first_name || '',
          last_name: c.last_name || '',
          company: c.company || '',
          position: c.position || '',
          connected_on: c.connected_on || '',
          email_address: c.email_address || '',
          profile_url: c.url || c.profile_url || '',
          crm_status: c.crmStatus || 'Ninguno',
          crm_notes: c.crmNotes || '',
          custom_name: c.customName || '',
          custom_company: c.customCompany || '',
          custom_position: c.customPosition || '',
          crm_date: c.crmDate || new Date().toISOString(),
          msg_count: c.msg_count || 0,
          latest_message: c.latest_message || '',
          raw_data: c
        }));
        
        try {
          const { error } = await supabase.from('contacts').upsert(chunk, { onConflict: 'contact_id, user_id' });
          if (error) console.error("Error upserting chunk:", error);
        } catch(e) {
          console.error("Exception upserting chunk:", e);
        }
      }
    }
    
    finalize();
  }

  if (errors.length > 0) {
    alert("⚠️ Alertas de Importación:\n\n" + errors.join("\n"));
  }
  setLoading(false);
}

async function processZip(zip) {
  const files = Object.keys(zip.files);
  let foundAny = false;

  // 1. Profile
  const profileFile = files.find(f => f.includes('Profile.csv'));
  if (profileFile) {
    const txt = await zip.files[profileFile].async('string');
    const parsed = Papa.parse(txt, { header: true, skipEmptyLines: true, quoteChar: '"', escapeChar: '"' });
    if (parsed.data[0]) {
      S.ownerName = `${parsed.data[0]['First Name']||''} ${parsed.data[0]['Last Name']||''}`.trim();
      S.loadedParts.profile = true;
      foundAny = true;
    }
  }

  // 2. Positions
  const posFile = files.find(f => f.includes('Positions.csv'));
  if (posFile) {
    const txt = await zip.files[posFile].async('string');
    const parsed = Papa.parse(txt, { header: true, skipEmptyLines: true, quoteChar: '"', escapeChar: '"' });
    const parsedPos = parsed.data.map(r => ({
      company: r['Company Name'] || '',
      title: r['Title'] || '',
      start: r['Started On'] || '',
      end: r['Finished On'] || ''
    })).filter(p => p.company || p.title);
    
    if (parsedPos.length > 0) {
      S.positions = parsedPos;
      S.loadedParts.positions = true;
      foundAny = true;
    }
  }

  // 3. Connections
  const connFile = files.find(f => /connection/i.test(f) && f.endsWith('.csv'));
  if (connFile) {
    const txt = await zip.files[connFile].async('string');
    const lines = txt.split('\n');
    const startIdx = lines.findIndex(l => l.includes('First Name'));
    if (startIdx !== -1) {
      const csvData = lines.slice(startIdx).join('\n');
      const parsed = Papa.parse(csvData, { header: true, skipEmptyLines: true, quoteChar: '"', escapeChar: '"' });
      if (parsed.data && parsed.data.length > 0) {
        buildContacts(parsed.data);
        S.loadedParts.connections = true;
        foundAny = true;
      }
    }
  }

  // 4. Messages
  const msgFile = files.find(f => f === 'messages.csv' || f.endsWith('/messages.csv'));
  if (msgFile) {
    const txt = await zip.files[msgFile].async('string');
    const parsed = Papa.parse(txt, { header: true, skipEmptyLines: true, quoteChar: '"', escapeChar: '"' });
    if (parsed.data && parsed.data.length > 0) {
      S.messages = parsed.data;
      S.loadedParts.messages = true;
      foundAny = true;
    }
  }

  if (!foundAny) {
    throw new Error("No se encontraron archivos oficiales de LinkedIn (como Connections.csv, Profile.csv o messages.csv) en este ZIP.");
  }
  return true;
}

async function processCSVOnly(file) {
  return new Promise((resolve, reject) => {
    Papa.parse(file, {
      header: true, skipEmptyLines: true,
      complete: r => {
        if (!r.data || r.data.length === 0) {
          reject(new Error("El archivo CSV está vacío."));
          return;
        }
        
        const firstRow = r.data[0];
        
        // 1. Is it Positions?
        if ('Company Name' in firstRow || 'Company name' in firstRow || 'Started On' in firstRow) {
          S.positions = r.data.map(r => ({
            company: r['Company Name'] || r['Company name'] || '',
            title: r['Title'] || r['title'] || '',
            start: r['Started On'] || r['Started on'] || '',
            end: r['Finished On'] || r['Finished on'] || ''
          })).filter(p => p.company || p.title);
          S.loadedParts.positions = true;
          resolve(true);
          return;
        }

        // 2. Is it Messages?
        if ('CONVERSATION ID' in firstRow || 'Conversation ID' in firstRow || ('From' in firstRow && 'Content' in firstRow)) {
          S.messages = r.data;
          S.loadedParts.messages = true;
          resolve(true);
          return;
        }

        // 3. Else treat as Connections
        const hasFirstName = 'First Name' in firstRow || 'First name' in firstRow || 'first_name' in firstRow || 'Nombre' in firstRow;
        if (!hasFirstName) {
          reject(new Error("El archivo CSV no contiene columnas reconocibles de LinkedIn (como First Name, Company Name, o Conversation ID)."));
          return;
        }

        const normalized = r.data.map(row => ({
          'First Name': row['First Name'] || row['First name'] || row['first_name'] || row['Nombre'] || '',
          'Last Name': row['Last Name'] || row['Last name'] || row['last_name'] || row['Apellido'] || '',
          'Company': row['Company'] || row['company'] || row['Empresa'] || '',
          'Position': row['Position'] || row['position'] || row['Title'] || row['title'] || row['Cargo'] || '',
          'Email Address': row['Email Address'] || row['Email'] || row['email'] || row['Correo'] || '',
          'URL': row['URL'] || row['url'] || row['LinkedIn Profile'] || '',
          'Connected On': row['Connected On'] || row['Connected on'] || row['Fecha de conexión'] || ''
        }));
        buildContacts(normalized);
        S.loadedParts.connections = true;
        resolve(true);
      },
      error: err => reject(err)
    });
  });
}

