function getCoordsForContact(country, company, position) {
  const compClean = norm(company);
  const posClean = norm(position);
  const fullText = `${compClean} ${posClean}`;

  let inferredCountry = country;
  let inferredCity = 'Ciudad';

  if (!inferredCountry || inferredCountry === 'Desconocido') {
    if (fullText.includes('mexico') || fullText.includes('cdmx') || fullText.includes('cancun') || fullText.includes('monterrey')) {
      inferredCountry = 'México'; inferredCity = fullText.includes('cancun') ? 'Cancún' : 'CDMX';
    } else if (fullText.includes('colombia') || fullText.includes('bogota') || fullText.includes('medellin')) {
      inferredCountry = 'Colombia'; inferredCity = 'Bogotá';
    } else if (fullText.includes('argentina') || fullText.includes('buenos aires')) {
      inferredCountry = 'Argentina'; inferredCity = 'Buenos Aires';
    } else if (fullText.includes('chile') || fullText.includes('santiago')) {
      inferredCountry = 'Chile'; inferredCity = 'Santiago';
    } else if (fullText.includes('espana') || fullText.includes('spain') || fullText.includes('madrid') || fullText.includes('barcelona')) {
      inferredCountry = 'España'; inferredCity = fullText.includes('barcelona') ? 'Barcelona' : 'Madrid';
    } else if (fullText.includes('uk') || fullText.includes('united kingdom') || fullText.includes('london') || fullText.includes('londres')) {
      inferredCountry = 'Reino Unido'; inferredCity = 'Londres';
    } else if (fullText.includes('germany') || fullText.includes('alemania') || fullText.includes('berlin') || fullText.includes('munich')) {
      inferredCountry = 'Alemania'; inferredCity = 'Berlín';
    } else if (fullText.includes('france') || fullText.includes('francia') || fullText.includes('paris')) {
      inferredCountry = 'Francia'; inferredCity = 'París';
    } else if (fullText.includes('italy') || fullText.includes('italia') || fullText.includes('milan') || fullText.includes('rome')) {
      inferredCountry = 'Italia'; inferredCity = 'Milán';
    } else if (fullText.includes('netherlands') || fullText.includes('amsterdam')) {
      inferredCountry = 'Países Bajos'; inferredCity = 'Ámsterdam';
    } else if (fullText.includes('switzerland') || fullText.includes('suiza') || fullText.includes('zurich')) {
      inferredCountry = 'Suiza'; inferredCity = 'Zúrich';
    } else if (fullText.includes('sweden') || fullText.includes('suecia') || fullText.includes('stockholm')) {
      inferredCountry = 'Suecia'; inferredCity = 'Estocolmo';
    } else if (fullText.includes('portugal') || fullText.includes('lisbon') || fullText.includes('lisboa')) {
      inferredCountry = 'Portugal'; inferredCity = 'Lisboa';
    } else if (fullText.includes('ireland') || fullText.includes('dublin')) {
      inferredCountry = 'Irlanda'; inferredCity = 'Dublín';
    } else if (/\b(usa|united states|miami|new york|california|texas|florida)\b/i.test(fullText)) {
      inferredCountry = 'Estados Unidos'; inferredCity = 'Miami';
    }
  }

  if (inferredCountry && COUNTRY_COORDS_JS[inferredCountry]) {
    return {
      country: inferredCountry,
      city: inferredCity,
      lat: COUNTRY_COORDS_JS[inferredCountry].lat,
      lng: COUNTRY_COORDS_JS[inferredCountry].lng
    };
  }

  return { country: inferredCountry || 'Desconocido', city: 'Desconocido', lat: 19.4326, lng: -99.1332 };
}

function buildContacts(rows) {
  const isInitialLoad = S.isDemoLoaded || !S.contacts || S.contacts.length === 0;

  if (isInitialLoad) {
    S.contacts = [];
    S.isDemoLoaded = false;
  }

  // Mapa de contactos existentes por URL o Nombre Único para evitar duplicados
  const existingMap = new Map();
  S.contacts.forEach(c => {
    const key = c.url ? c.url : norm(c.name);
    if (key) existingMap.set(key, c);
  });

  const incomingKeys = new Set();
  const mergedContacts = [];

  rows.forEach((row) => {
    const fn = (row['First Name'] || '').trim();
    const ln = (row['Last Name'] || '').trim();
    const name = `${fn} ${ln}`.trim();
    if (!name) return;

    let company = (row['Company'] || row['company'] || '').trim();
    let position = (row['Position'] || row['position'] || '').trim();
    if (/\b\d+[\d,.]*\s*(followers?|seguidores?)\b/i.test(company) || company.toLowerCase().includes('follower')) company = '';
    if (/\b\d+[\d,.]*\s*(followers?|seguidores?)\b/i.test(position) || position.toLowerCase().includes('follower')) position = '';

    const email = (row['Email Address'] || row['email'] || '').trim();
    const url = (row['URL'] || row['url'] || '').trim();
    const connectedOn = (row['Connected On'] || row['connectedOn'] || '').trim();
    const yearsAgo = connectedYearsAgo(connectedOn);
    
    const initialCountry = inferCountry(email, company, position);
    const coords = getCoordsForContact(initialCountry, company, position);
    const hierarchy = inferHierarchy(position);
    const sector = inferSector(position, company);

    let jobStatus = "🟢 Vigente Confirmado";
    if (connectedOn.includes("2025") || connectedOn.includes("2024")) jobStatus = "🟡 Vigente Probable";
    else if (connectedOn && !connectedOn.includes("2026")) jobStatus = "🔍 Por Corroborar";
    if (!company) jobStatus = "⚠️ Sin Empresa Registrada";

    const key = url ? url : norm(name);
    incomingKeys.add(key);

    if (existingMap.has(key)) {
      // ACTUALIZACIÓN INTELIGENTE (Smart Re-Sync): Preserva los roles enriquecidos en vivo (HarvestAPI/Apify), notas CRM, descartados y scoring ICP
      const existing = existingMap.get(key);
      
      // Si el contacto ya fue enriquecido previamente con Apify/HarvestAPI, MANTIENE su rol y empresa actualizados de 2026 sin regresionar al CSV antiguo
      if (!existing.harvest_enriched && !existing.last_updated_apify) {
        existing.company = company || existing.company;
        existing.position = position || existing.position;
        existing.hierarchy = hierarchy;
        existing.sector = sector;
      }

      existing.email = email || existing.email;
      existing.connectedOn = connectedOn || existing.connectedOn;
      existing.disconnectedFromLinkedin = false;
      mergedContacts.push(existing);
    } else {
      // NUEVO CONTACTO DE LINKEDIN
      mergedContacts.push({
        id: mergedContacts.length,
        name, company, position, originalName: name, originalCompany: company, originalPosition: position,
        email, url, connectedOn, connectedYearsAgo: yearsAgo,
        country: coords.country, city: coords.city, lat: coords.lat, lng: coords.lng,
        jobStatus, hierarchy, sector, score: 0
      });
    }
  });

  // AUTO-PURGA DE CONTACTOS ELIMINADOS EN LINKEDIN:
  // Si fue removido en LinkedIn y NO tiene notas/tratos activos en CRM, se limpia automáticamente
  if (!isInitialLoad) {
    let autoPurgedCount = 0;
    S.contacts.forEach(c => {
      const key = c.url ? c.url : norm(c.name);
      if (!incomingKeys.has(key)) {
        const hasActiveDeal = c.crmStatus && c.crmStatus !== 'Ninguno' && c.crmStatus !== 'Descartado';
        if (hasActiveDeal) {
          c.disconnectedFromLinkedin = true;
          mergedContacts.push(c);
        } else {
          autoPurgedCount++;
        }
      }
    });
    if (autoPurgedCount > 0) {
      console.log(`[SmartMerge] Auto-limpieza ejecutada: ${autoPurgedCount} contactos eliminados en LinkedIn fueron removidos del tablero.`);
      showToast(`Auto-limpieza: ${autoPurgedCount} contactos eliminados en LinkedIn fueron purgados.`, '🧹');
    }
  }

  mergedContacts.forEach((c, idx) => c.id = idx);
  S.contacts = mergedContacts;
  saveLocalVault();
}

async function normalizeWithAPI() {
  const unknownSet = new Set();
  S.contacts.forEach(c => {
    if (c.country === 'Desconocido' || c.country === '') {
      const company = (c.originalCompany || c.company || '').trim();
      const position = (c.originalPosition || c.position || '').trim();
      if (company || position) {
        unknownSet.add(`${company} | ${position}`);
      }
    }
  });

  const unknownList = Array.from(unknownSet);
  if (unknownList.length === 0) return;

  try {
    setLoading(true, 95);
    // Cambiamos el loader text temporalmente
    const loadingP = document.querySelector('.loading p');
    const oldText = loadingP.innerText;
    loadingP.innerText = `Limpiando ${unknownList.length} roles nuevos con Claude AI...`;

    // Batching to avoid huge payloads, but Claude can handle ~150 easily.
    const res = await fetch("http://localhost:8000/normalize", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ strings: unknownList })
    });

    if (res.ok) {
      const data = await res.json();
      // Merge into normalizedLocations
      window.normalizedLocations = window.normalizedLocations || {};
      Object.assign(window.normalizedLocations, data);

      // Re-evaluate country for everyone
      S.contacts.forEach(c => {
        c.country = inferCountry(c.email, c.originalCompany || c.company, c.originalPosition || c.position);
      });
    }
    
    loadingP.innerText = oldText;
  } catch (err) {
    console.warn("No se pudo conectar a la API local de Claude:", err);
  }
}

