let currentTileLayer = null;
const TILE_SERVERS = {
  dark: {
    url: 'https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}.png',
    attr: '&copy; CARTO &copy; OpenStreetMap',
    subdomains: 'abcd'
  },
  satellite: {
    url: 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
    attr: 'Tiles &copy; Esri'
  },
  voyager: {
    url: 'https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}.png',
    attr: '&copy; CARTO &copy; OpenStreetMap',
    subdomains: 'abcd'
  },
  osm: {
    url: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
    attr: '&copy; OpenStreetMap contributors'
  }
};

function switchGisTileLayer(mode) {
  if (!gisMap) return;

  S.activeGisTileMode = mode;

  // Remove ALL existing tile layers to prevent overlap
  gisMap.eachLayer(layer => {
    if (layer instanceof L.TileLayer) {
      try { gisMap.removeLayer(layer); } catch(e) {}
    }
  });

  const config = TILE_SERVERS[mode] || TILE_SERVERS.dark;
  const opts = {
    attribution: config.attr,
    noWrap: true,
    maxZoom: 18
  };
  if (config.subdomains) {
    opts.subdomains = config.subdomains;
  }

  currentTileLayer = L.tileLayer(config.url, opts).addTo(gisMap);
  currentTileLayer.bringToBack();

  const sel = document.getElementById('gis-tile-select');
  if (sel && sel.value !== mode) {
    sel.value = mode;
  }

  setTimeout(() => {
    if (gisMap) gisMap.invalidateSize();
  }, 100);

  if (typeof showToast === 'function') {
    const labelMap = { dark: 'Cyberpunk Oscuro', satellite: 'Satelital HD (Esri)', voyager: 'Carto Voyager', osm: 'OpenStreetMap' };
    showToast(`Mapa cambiado: ${labelMap[mode] || mode}`, '🗺️');
  }
}

function filterNetworkByCountry(country) {
  const sel = document.getElementById('net-country');
  if (sel) {
    sel.value = country;
    applyNetworkFilters();
    showToast(`Filtrando red por ${country}`, '🌐');
  }
}

function initGisMap(contacts) {
  const mapContainer = document.getElementById('gis-map-container');
  const mapCard = document.getElementById('map-gis-card');
  if (!mapContainer || !mapCard) return;

  const validContacts = (contacts || []).filter(c => c && c.country && c.country !== 'Desconocido');
  if (validContacts.length === 0) {
    mapCard.style.display = 'none';
    return;
  }
  mapCard.style.display = 'block';

  if (!gisMap) {
    gisMap = L.map('gis-map-container', {
      center: [20, -10],
      zoom: 2,
      minZoom: 2,
      maxZoom: 14,
      zoomControl: true,
      worldCopyJump: false
    });

    gisLayerGroup = L.layerGroup().addTo(gisMap);
  }

  const activeMode = S.activeGisTileMode || 'dark';
  switchGisTileLayer(activeMode);

  gisLayerGroup.clearLayers();

  const locationGroups = {};
  validContacts.forEach(c => {
    const country = c.country;
    const city = c.city || '';
    
    let lat = c.lat;
    let lng = c.lng;

    // Use city coords lookup if available
    const cityCoords = getCityCoords(city, country);
    if (cityCoords) {
      lat = cityCoords[0];
      lng = cityCoords[1];
    }

    if (!lat || !lng) return;

    const normCity = normalizeCityName(city);
    const displayCity = normCity === 'cdmx' ? 'CDMX' : (city || country);
    const key = `${country}__${normCity || country.toLowerCase().trim()}`;

    if (!locationGroups[key]) {
      locationGroups[key] = {
        country: country,
        city: displayCity,
        lat: lat,
        lng: lng,
        contacts: []
      };
    }
    locationGroups[key].contacts.push(c);
  });

  let mappedCount = 0;
  const bounds = [];

  Object.values(locationGroups).forEach(group => {
    const count = group.contacts.length;
    mappedCount += count;
    bounds.push([group.lat, group.lng]);

    const isHigh = count >= 25;
    const isMid = count >= 8 && count < 25;
    const circleRadius = Math.min(26, Math.max(11, 9 + Math.log2(count + 1) * 3.4));
    const circleColor = isHigh ? '#7c3aed' : (isMid ? '#2563eb' : '#10b981');
    const borderColor = isHigh ? '#c4b5fd' : (isMid ? '#93c5fd' : '#6ee7b7');

    const cLevels = group.contacts.filter(c => c.hierarchy === 'C-Level').length;
    const directors = group.contacts.filter(c => c.hierarchy === 'Director').length;
    const managers = group.contacts.filter(c => c.hierarchy === 'Gerente').length;

    const marker = L.circleMarker([group.lat, group.lng], {
      radius: circleRadius,
      fillColor: circleColor,
      color: borderColor,
      weight: 2.5,
      opacity: 0.95,
      fillOpacity: 0.85
    });

    marker.bindTooltip(`<b>${count}</b>`, {
      permanent: true,
      direction: 'center',
      className: 'gis-circle-tooltip'
    });

    const popupContent = `
      <div style="font-family:'Outfit',sans-serif; padding:4px; font-size:12px; color:#f8fafc; min-width:180px;">
        <div style="font-weight:800; color:#a5b4fc; margin-bottom:6px; font-size:13px; border-bottom:1px solid rgba(255,255,255,0.1); padding-bottom:4px;">
          📍 ${group.city}, ${group.country}
        </div>
        <div style="font-size:11px; margin-bottom:8px; line-height:1.6; color:#cbd5e1;">
          <div>👑 <strong>C-Level:</strong> <span style="color:#c084fc;">${cLevels}</span></div>
          <div>🎯 <strong>Directores:</strong> <span style="color:#60a5fa;">${directors}</span></div>
          <div>🤝 <strong>Gerentes:</strong> <span style="color:#34d399;">${managers}</span></div>
          <div style="color:#10b981; font-weight:700; margin-top:4px;">Total: ${count} contactos cálidos</div>
        </div>
        <button class="mini-btn primary" onclick="filterNetworkByCountry('${group.country}')" style="width:100%; font-size:10px; padding:4px; font-weight:700; background:linear-gradient(135deg, var(--accent), var(--green)); border:none; color:white;">
          ⚡ Filtrar Mi Red por ${group.country}
        </button>
      </div>
    `;

    marker.bindPopup(popupContent);
    gisLayerGroup.addLayer(marker);
  });

  const countBadge = document.getElementById('map-contact-count');
  if (countBadge) {
    countBadge.textContent = `${mappedCount.toLocaleString()} contactos mapeados`;
  }

  if (bounds.length > 0) {
    try {
      gisMap.fitBounds(bounds, { padding: [40, 40], maxZoom: 6 });
    } catch(e) {}
  }

  setTimeout(() => {
    if (gisMap) gisMap.invalidateSize();
  }, 200);
}

