// PROFILE
// ═══════════════════════════════════════════════════════════════════════
function renderProfile() {
  if (!S.positions.length && !S.ownerName) return;
  const el = document.getElementById('profile-content');
  const name = S.isDemoMode ? 'Propietario Anonimizado' : (S.ownerName || 'Propietario');
  const activeIdx = S.activePositionIndex || 0;
  let html = `<div style="margin-bottom:16px"><div style="font-size:18px;font-weight:700">${name}</div>`;
  if (S.positions[activeIdx]) {
    const compName = S.isDemoMode ? 'Empresa Anonimizada SA' : S.positions[activeIdx].company;
    html += `<div style="font-size:12px;color:var(--muted2);margin-top:3px">Contexto Activo para Pitches: <strong>${S.positions[activeIdx].title} @ ${compName}</strong></div>`;
  }
  html += `</div><div class="timeline">`;
  S.positions.forEach((p, i) => {
    const isActive = i === activeIdx;
    const activeClass = isActive ? 'active' : '';
    const endLabel = p.end || 'Actual';
    html += `<div class="tl-item ${activeClass}" style="cursor:pointer;" onclick="selectActivePosition(${i})">
      <div class="tl-dot"></div>
      <div class="tl-company">${S.isDemoMode ? 'Empresa Anonimizada SA' : p.company}</div>
      <div class="tl-role">${p.title}</div>
      <div class="tl-period">${p.start} → ${endLabel}</div>
      ${isActive ? `<span class="badge badge-green tl-toggle">● Contexto activo para pitches y scoring</span>` : `<span class="badge badge-muted tl-toggle">Hacer contexto activo</span>`}
    </div>`;
  });
  html += '</div>';
  el.innerHTML = html;
}

function selectActivePosition(idx) {
  S.activePositionIndex = idx;
  // Recalculate scores based on the new active position
  S.contacts.forEach(c => { c.score = scoreContact(c); });
  icpContacts = S.contacts.filter(c => c.score >= 40).sort((a,b) => b.score - a.score);
  
  // Re-render and update UI
  renderProfile();
  renderNetwork();
  renderICP();
  renderHeader();
  renderPurge();
  renderMessages();
}

