// NETWORK
// ═══════════════════════════════════════════════════════════════════════
function populateFilters() {
  const countries = [...new Set(S.contacts.map(c => c.country))].sort();
  const sel = document.getElementById('net-country');
  sel.innerHTML = '<option value="">🌎 Todos los países</option>';
  countries.forEach(c => {
    const o = document.createElement('option'); o.value = c;
    o.textContent = countryFlag(c); sel.appendChild(o);
  });
  const sectors = [...new Set(S.contacts.map(c => c.sector))].sort();
  const sels = document.getElementById('net-sector');
  sels.innerHTML = '<option value="">🏭 Todos los sectores</option>';
  sectors.forEach(s => {
    const o = document.createElement('option'); o.value = s; o.textContent = s; sels.appendChild(o);
  });

  // Populate ICP Role Selector
  const icpRoleSelect = document.getElementById('icp-role-select');
  if (icpRoleSelect) {
    icpRoleSelect.innerHTML = S.positions.map((p, idx) => 
      `<option value="${idx}">${p.title} @ ${p.company}</option>`
    ).join('') || '<option value="">Sin cargos cargados</option>';
    icpRoleSelect.value = S.activePositionIndex || 0;
  }
}

function changeIcpActiveRole(val) {
  const idx = parseInt(val);
  if (isNaN(idx)) return;
  selectActivePosition(idx);
}

['net-search','net-country','net-hier','net-sector'].forEach(id => {
  document.getElementById(id).addEventListener('input', () => {
    const hierVal = document.getElementById('net-hier').value;
    S.filterClassA = false;
    if (hierVal) {
      S.activeKpiFilter = hierVal;
    } else {
      S.activeKpiFilter = 'total';
    }
    updateKpiHighlights();
    applyNetworkFilters();
  });
});

let filterVerifiedOnly = false;
function toggleVerifiedFilter() {
  filterVerifiedOnly = !filterVerifiedOnly;
  const btn = document.getElementById('btn-filter-verified');
  if (btn) {
    if (filterVerifiedOnly) {
      btn.style.background = 'var(--green)';
      btn.style.color = '#fff';
    } else {
      btn.style.background = 'var(--surface)';
      btn.style.color = 'var(--green)';
    }
  }
  applyNetworkFilters();
}

function applyNetworkFilters() {
  const search = norm(document.getElementById('net-search').value);
  const country = document.getElementById('net-country').value;
  const hier = document.getElementById('net-hier').value;
  const sector = document.getElementById('net-sector').value;

  // Si hay búsqueda por texto manual, identificar contactos con mensajes coincidentes en S.messages
  let msgMatchedUrlsAndNames = new Set();
  if (search && S.messages && S.messages.length > 0) {
    S.messages.forEach(m => {
      const text = norm(getRowVal(m, 'CONTENT') || getRowVal(m, 'TEXT') || getRowVal(m, 'CONTENT BODY') || m.content || m.text || '');
      if (text.includes(search)) {
        const fromName = getRowVal(m, 'FROM') || getRowVal(m, 'SENDER_NAME') || m.from || '';
        const toName = getRowVal(m, 'TO') || getRowVal(m, 'RECIPIENT_NAME') || m.to || '';
        const fromUrl = m.SENDER_URL || m.FROM_URL || '';
        const toUrl = m.TO_URL || m.RECIPIENT_URL || '';
        if (fromName) msgMatchedUrlsAndNames.add(norm(fromName));
        if (toName) msgMatchedUrlsAndNames.add(norm(toName));
        if (fromUrl) msgMatchedUrlsAndNames.add(fromUrl);
        if (toUrl) msgMatchedUrlsAndNames.add(toUrl);
      }
    });
  }

  filteredContacts = S.contacts.filter(c => {
    if ((c.crmStatus === 'Descartado' || c.discardedFromPurge) && !S.showDiscarded) return false;
    if (search) {
      const nameNorm = norm(c.name || '');
      const posNorm = norm(c.position || '');
      const compNorm = norm(c.company || '');
      const notesNorm = norm(c.crmNotes || '');
      const postNorm = norm(c.last_post_text || '');
      
      const inBasic = nameNorm.includes(search) || posNorm.includes(search) || compNorm.includes(search) || notesNorm.includes(search) || postNorm.includes(search);
      const inMsg = msgMatchedUrlsAndNames.has(nameNorm) || (c.url && msgMatchedUrlsAndNames.has(c.url));
      if (!inBasic && !inMsg) return false;
    }
    if (country && c.country !== country) return false;
    if (hier && c.hierarchy !== hier) return false;
    if (sector && c.sector !== sector) return false;
    if (S.filterClassA && c.score < 60) return false;
    if (filterVerifiedOnly && !c.harvest_enriched) return false;
    return true;
  });

  // Priorizar perfiles verificados en vivo (HarvestAPI) primero, luego por score
  filteredContacts.sort((a, b) => {
    const aVer = a.harvest_enriched ? 1 : 0;
    const bVer = b.harvest_enriched ? 1 : 0;
    if (bVer !== aVer) return bVer - aVer;
    return (b.score || 0) - (a.score || 0);
  });

  renderNetworkTable();
}

function filterNetworkBy(type) {
  const hierSel = document.getElementById('net-hier');
  S.activeKpiFilter = type;
  
  if (type === 'total') {
    hierSel.value = "";
    S.filterClassA = false;
  } else if (type === 'C-Level' || type === 'Director' || type === 'Gerente') {
    hierSel.value = type;
    S.filterClassA = false;
  } else if (type === 'clase-a') {
    hierSel.value = "";
    S.filterClassA = true;
  }
  
  updateKpiHighlights();
  applyNetworkFilters();
}

function updateKpiHighlights() {
  document.querySelectorAll('#net-kpis .kpi-card').forEach(c => c.classList.remove('active-filter'));
  const activeType = S.activeKpiFilter || 'total';
  const card = document.getElementById('kpicard-' + activeType);
  if (card) card.classList.add('active-filter');
}

function renderNetwork() {
  const activeContacts = S.contacts.filter(c => c.crmStatus !== 'Descartado' && !c.discardedFromPurge);
  const total = activeContacts.length;
  const hier = {};
  activeContacts.forEach(c => { hier[c.hierarchy] = (hier[c.hierarchy]||0)+1; });
  const countries = {};
  activeContacts.forEach(c => { countries[c.country] = (countries[c.country]||0)+1; });
  const identified = Object.entries(countries).filter(([k]) => k !== 'Desconocido').sort((a,b)=>b[1]-a[1]);
  const classa = activeContacts.filter(c=>c.score>=60).length;

  const activeF = S.activeKpiFilter || 'total';
  document.getElementById('net-kpis').innerHTML = `
    <div class="kpi-card ${activeF==='total'?'active-filter':''}" id="kpicard-total" onclick="filterNetworkBy('total')"><div class="kpi-label">Total</div><div class="kpi-value">${total.toLocaleString()}</div></div>
    <div class="kpi-card ${activeF==='C-Level'?'active-filter':''}" id="kpicard-C-Level" onclick="filterNetworkBy('C-Level')"><div class="kpi-label">C-Level</div><div class="kpi-value" style="color:var(--purple)">${hier['C-Level']||0}</div><div class="kpi-sub">${((hier['C-Level']||0)/total*100).toFixed(1)}%</div></div>
    <div class="kpi-card ${activeF==='Director'?'active-filter':''}" id="kpicard-Director" onclick="filterNetworkBy('Director')"><div class="kpi-label">Directores</div><div class="kpi-value" style="color:var(--accent)">${hier['Director']||0}</div></div>
    <div class="kpi-card ${activeF==='Gerente'?'active-filter':''}" id="kpicard-Gerente" onclick="filterNetworkBy('Gerente')"><div class="kpi-label">Gerentes</div><div class="kpi-value" style="color:var(--green)">${hier['Gerente']||0}</div></div>
    <div class="kpi-card" id="kpicard-paises"><div class="kpi-label">Países ID</div><div class="kpi-value">${identified.length}</div></div>
    <div class="kpi-card ${activeF==='clase-a'?'active-filter':''}" id="kpicard-clase-a" onclick="filterNetworkBy('clase-a')"><div class="kpi-label">Clase A (≥60)</div><div class="kpi-value" style="color:var(--amber)">${classa}</div><div class="kpi-sub">Dunbar: 150</div></div>
  `;

  // Charts
  const isL = document.body.classList.contains('light');
  const txtColor = isL ? '#475569' : '#94a3b8';
  const gridColor = isL ? '#e2e8f0' : '#1e2235';
  const barBgColor = isL ? '#2563eb' : '#3b82f6';
  const doughnutBgs = isL ? ['#7e22ce','#2563eb','#15803d','#cbd5e1'] : ['#c084fc','#3b82f6','#10b981','#2b2e46'];

  if (chartHier) chartHier.destroy();
  if (chartCountries) chartCountries.destroy();
  document.getElementById('net-charts').style.display = 'grid';
  const cHier = document.getElementById('chart-hier').getContext('2d');
  chartHier = new Chart(cHier, {
    type: 'doughnut',
    data: {
      labels: ['C-Level','Director','Gerente','Otros'],
      datasets: [{ data: [hier['C-Level']||0, hier['Director']||0, hier['Gerente']||0, hier['Otros']||0], backgroundColor: doughnutBgs, borderWidth: 0 }]
    },
    options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { labels: { color: txtColor, font: { size: 10 } } } }, cutout: '65%' }
  });
  const top10 = identified.slice(0,10);
  const cCountries = document.getElementById('chart-countries').getContext('2d');
  chartCountries = new Chart(cCountries, {
    type: 'bar',
    data: {
      labels: top10.map(([k])=>k),
      datasets: [{ data: top10.map(([,v])=>v), backgroundColor: barBgColor, borderRadius: 4 }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      indexAxis: 'y',
      plugins: { legend: { display: false } },
      scales: {
        x: { ticks: { color: txtColor, font:{size:9} }, grid: { display: false } },
        y: { ticks: { color: txtColor, autoSkip: false, font:{size:11, family:'Outfit'} }, grid: { display: false } }
      }
    }
  });
  initGisMap(S.contacts);
  renderNetworkTable();
}

