function normalizeCityName(city) {
  if (!city || city === 'Desconocido') return '';
  let norm = city.toLowerCase().trim()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // quitar acentos
    .replace(/^(area metropolitana de|ciudad de|distrito federal de|d\.f\.|df|d\.c\.)\s+/g, '');
  
  if (norm.includes('cdmx') || norm.includes('mexico city') || norm.includes('mexico') || norm.includes('alvaro obregon') || norm.includes('ecatepec') || norm.includes('hidalgo')) {
    return 'cdmx';
  }
  if (norm.includes('guadalajara') || norm.includes('jalisco') || norm.includes('tonala')) return 'guadalajara';
  if (norm.includes('monterrey') || norm.includes('nuevo leon')) return 'monterrey';
  if (norm.includes('bogota')) return 'bogota';
  if (norm.includes('medellin')) return 'medellin';
  if (norm.includes('sao paulo')) return 'sao paulo';
  if (norm.includes('buenos aires') || norm.includes('caba')) return 'buenos aires';
  if (norm.includes('santiago')) return 'santiago';
  if (norm.includes('lima')) return 'lima';
  if (norm.includes('san jose') || norm.includes('costa rica')) return 'san jose';
  if (norm.includes('panama')) return 'panama';
  if (norm.includes('guatemala')) return 'guatemala';
  if (norm.includes('san salvador') || norm.includes('el salvador')) return 'san salvador';
  if (norm.includes('tegucigalpa') || norm.includes('honduras')) return 'tegucigalpa';
  if (norm.includes('managua') || norm.includes('nicaragua')) return 'managua';
  if (norm.includes('santo domingo') || norm.includes('dominicana')) return 'santo domingo';
  return norm;
}

function getCityCoords(city, country) {
  const normCity = normalizeCityName(city);
  const genericCities = ['ciudad', 'desconocido', 'pueblo', 'area', 'region', 'provincia', 'department', 'departamento'];

  if (normCity && !genericCities.includes(normCity)) {
    if (CITY_COORDS[normCity]) return CITY_COORDS[normCity];
    // Try partial match
    for (const [k, v] of Object.entries(CITY_COORDS)) {
      if (normCity.includes(k) || k.includes(normCity)) return v;
    }
  }
  // Fallback to country centroid
  if (country && COUNTRY_COORDS[country]) return COUNTRY_COORDS[country];
  return null;
}

function renderGISMap(identifiedCountries, allContacts) {
  const mapCard = document.getElementById('map-gis-card');
  if (!mapCard) return;

  const validContacts = allContacts.filter(c => c.lat && c.lng && c.country !== 'Desconocido');

  if (validContacts.length === 0 && identifiedCountries.length === 0) {
    mapCard.style.display = 'none';
    return;
  }
  mapCard.style.display = 'block';

  document.getElementById('map-contact-count').textContent = `${validContacts.length.toLocaleString()} contactos geolocalizados`;

  if (typeof L === 'undefined') return;

  const tileUrl = 'https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png';

  if (!gisMapInstance) {
    gisMapInstance = L.map('gis-map-container', {
      center: [15.0, -70.0],
      zoom: 3,
      zoomControl: true,
      attributionControl: false,
      maxBounds: [[-90, -200], [90, 200]],
      maxBoundsViscosity: 1.0
    });

    L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
      maxZoom: 14,
      noWrap: true,
      bounds: [[-90, -180], [90, 180]]
    }).addTo(gisMapInstance);
  }

  // Limpiar marcadores anteriores para evitar duplicados en re-renders
  gisMapMarkers.forEach(m => gisMapInstance.removeLayer(m));
  gisMapMarkers = [];

  // Agrupar por ciudad usando getCityCoords()
  const locationGroups = {};
  allContacts.forEach(c => {
    const country = c.country;
    const city = c.city || '';
    if (!country || country === 'Desconocido') return;

    const coords = getCityCoords(city, country);
    if (!coords) return;

    // Key: ciudad limpia normalizada o country si la ciudad es genérica/desconocida
    const normCity = normalizeCityName(city);
    const genericCities = ['ciudad', 'desconocido', 'pueblo', 'area', 'region', 'provincia', 'department', 'departamento', ''];
    const displayCity = (!normCity || genericCities.includes(normCity)) ? country : (normCity === 'cdmx' ? 'CDMX' : city);
    const groupKey = `${country}__${normCity || country.toLowerCase().trim()}`;

    if (!locationGroups[groupKey]) {
      locationGroups[groupKey] = {
        country: country,
        city: displayCity,
        lat: coords[0],
        lng: coords[1],
        contacts: []
      };
    }
    locationGroups[groupKey].contacts.push(c);
  });

  let totalMapped = 0;
  Object.values(locationGroups).forEach(group => {
    const count = group.contacts.length;
    totalMapped += count;
    const radius = Math.min(30, Math.max(7, 5 + Math.log2(count + 1) * 5));
    const clevelCount = group.contacts.filter(c => c.hierarchy === 'C-Level').length;
    const hasClevel = clevelCount > 0;

    const circle = L.circleMarker([group.lat, group.lng], {
      radius: radius,
      fillColor: hasClevel ? '#7c3aed' : '#4f46e5',
      color: hasClevel ? '#c4b5fd' : '#818cf8',
      weight: 2,
      opacity: 1,
      fillOpacity: 0.7
    }).addTo(gisMapInstance);

    // Label con número dentro del círculo (perfectamente centrado)
    if (count > 1) {
      const textMarker = L.marker([group.lat, group.lng], {
        icon: L.divIcon({
          className: '',
          html: `<div style="color:#ffffff; font-family:'Outfit',sans-serif; font-weight:800; font-size:${count > 99 ? 9 : (count > 9 ? 10 : 11)}px; text-align:center; line-height:${radius * 2}px; width:${radius * 2}px; pointer-events:none; text-shadow:0 1px 4px rgba(0,0,0,0.9);">${count}</div>`,
          iconSize: [radius * 2, radius * 2],
          iconAnchor: [radius, radius]
        }),
        interactive: false
      }).addTo(gisMapInstance);
      gisMapMarkers.push(textMarker);
    }

    const topContacts = group.contacts
      .sort((a,b) => (b.score||0)-(a.score||0))
      .slice(0,3)
      .map(c => `<div style="font-size:10px;color:#cbd5e1;margin-top:2px">• ${c.name} <span style="color:#94a3b8;">(${c.position||'—'})</span></div>`)
      .join('');

    const popupHtml = `
      <div style="font-family:'Outfit',sans-serif;padding:6px;min-width:180px;">
        <div style="font-weight:700;font-size:13px;margin-bottom:6px;color:#a5b4fc;">
          ${group.city !== group.country ? group.city + ', ' : ''}${group.country}
        </div>
        <div style="display:flex;gap:12px;margin-bottom:6px;">
          <span style="color:#10b981;font-weight:700;font-size:14px;">${count}</span>
          <span style="color:#94a3b8;font-size:11px;align-self:center;">contactos cálidos</span>
        </div>
        ${clevelCount > 0 ? `<div style="font-size:10px;color:#c4b5fd;margin-bottom:4px;">★ ${clevelCount} C-Level / Ejecutivo</div>` : ''}
        ${topContacts}
        <button onclick="filterNetworkByCountry('${group.country}')" style="margin-top:8px;background:#4f46e5;color:white;border:none;padding:5px 10px;border-radius:6px;font-size:10px;cursor:pointer;width:100%;font-weight:700;">
          Ver todos en ${group.country}
        </button>
      </div>
    `;
    circle.bindPopup(popupHtml);
    gisMapMarkers.push(circle);
  });

  document.getElementById('map-contact-count').textContent = `${totalMapped.toLocaleString()} contactos geolocalizados`;

  setTimeout(() => {
    if (gisMapInstance) gisMapInstance.invalidateSize();
  }, 250);
}

function filterNetworkByCountry(countryName) {
  const sel = document.getElementById('net-country');
  if (sel) {
    sel.value = countryName;
    sel.dispatchEvent(new Event('input'));
  }
}

let sortCol = 'score', sortDir = -1;
function sortTable(col) {
  if (sortCol === col) sortDir *= -1; else { sortCol = col; sortDir = -1; }
  document.querySelectorAll('#net-table th').forEach(th => th.classList.remove('sorted'));
  filteredContacts.sort((a,b) => {
    const av = a[col], bv = b[col];
    if (typeof av === 'number') return (av-bv)*sortDir;
    return String(av||'').localeCompare(String(bv||''))*sortDir;
  });
  renderNetworkTable();
}

function renderNetworkTable(showMore = false) {
  const tbody = document.getElementById('net-tbody');
  const empty = document.getElementById('net-empty');
  if (!filteredContacts.length) { tbody.innerHTML=''; empty.style.display='block'; return; }
  empty.style.display = 'none';

  if (!showMore) {
    S.networkTableLimit = 40; // Mostrar 40 empresas principales inicialmente (rendimiento ultra-rápido)
  }

  // Agrupar por empresa
  const grouped = {};
  filteredContacts.forEach(c => {
    const comp = (getDisplayCompany(c)).trim();
    if (!grouped[comp]) grouped[comp] = [];
    grouped[comp].push(c);
  });

  // Ordenar empresas por volumen de contactos (descendente)
  const sortedCompanies = Object.entries(grouped).sort((a,b) => b[1].length - a[1].length);
  const totalCompanies = sortedCompanies.length;
  const visibleCompanies = sortedCompanies.slice(0, S.networkTableLimit || 40);

  let html = '';
  visibleCompanies.forEach(([comp, contacts]) => {
    html += `
      <tr style="background:var(--surface);">
        <td colspan="8" style="padding: 8px 12px; font-weight: 700; color: var(--accent); border-top: 2px solid var(--border); border-bottom: 1px solid var(--border);">
          🏢 ${comp} <span class="badge badge-muted" style="margin-left:8px;">${contacts.length} conexiones</span>
        </td>
      </tr>
    `;
    
    html += contacts.map((c, idx) => {
      const dName = getDisplayName(c, idx);
      const parts = dName.split(' ').filter(p => p.length > 0);
      const ini = (parts.length > 1 ? parts[0][0] + parts[1][0] : (parts[0] ? parts[0][0] : '?')).toUpperCase();
      const colors = ['#3b82f6', '#10b981', '#f59e0b', '#8b5cf6', '#ef4444', '#06b6d4'];
      const avatarColor = colors[(c.name||'x').length % colors.length];
      const isSelected = selectedContactIds.has(c.id);

      const postBadge = c.last_post_text 
        ? `<span class="badge badge-purple" title="Último post: ${c.last_post_text.replace(/"/g, '&quot;')}" style="font-size:8px; cursor:help; padding:1px 5px;">📝 Post</span>`
        : '';

      return `
        <tr class="${isSelected ? 'row-selected' : ''}">
          <td style="text-align:center; padding:7px 4px;">
            <input type="checkbox" class="net-row-cb" value="${c.id}" ${isSelected ? 'checked' : ''} onchange="toggleContactSelection(${c.id}, this.checked)" style="cursor:pointer; accent-color:var(--accent);">
          </td>
          <td style="padding-left:14px;">
            <div style="display:flex; align-items:center; gap:10px;">
              <div style="width:24px; height:24px; border-radius:50%; background:${avatarColor}20; color:${avatarColor}; display:flex; align-items:center; justify-content:center; font-size:9px; font-weight:800; flex-shrink:0;">${ini}</div>
              <div class="td-name" style="display:flex; align-items:center; gap:6px; flex-wrap:wrap;">
                ${getDisplayNameHTML(c, idx)}
                ${c.harvest_enriched ? '<span class="badge" style="font-size:8px; padding:2px 6px; background:rgba(16,185,129,0.18); color:#6ee7b7; border:1px solid rgba(16,185,129,0.4); font-weight:700;">✨ Verificado Live</span>' : `<span class="badge ${c.jobStatus && c.jobStatus.includes('🟢') ? 'badge-green' : (c.jobStatus && c.jobStatus.includes('🟡') ? 'badge-amber' : 'badge-muted')}" style="font-size:8px; padding:1px 5px;">${c.jobStatus || '🟢 Vigente'}</span>`}
                ${postBadge}
              </div>
            </div>
          </td>
          <td><div class="td-sub" title="${c.position}">${c.position||'—'}</div></td>
          <td style="font-size:11px;white-space:nowrap">${countryFlag(c.country)}</td>
          <td><span class="badge badge-muted" style="font-size:8px">${c.sector}</span></td>
          <td>${hierarchyBadge(c.hierarchy)}</td>
          <td><div class="score-wrap"><div class="score-bar"><div class="score-fill" style="width:${c.score}%;background:${scoreColor(c.score)}"></div></div><span class="score-num">${c.score}</span></div></td>
          <td style="white-space:nowrap; text-align:right;">
            <button class="mini-btn" onclick="enrichSingleContactLive(${c.id})" title="Actualizar perfil y último post con HarvestAPI" style="margin-right:4px; padding:2px 6px; color:var(--green); border-color:rgba(16,185,129,0.4);">⚡</button>
            <select class="filter-input" style="font-size:10px; padding:2px 4px; border-radius:6px; height:auto; width:90px; margin-right:6px; background:var(--bg); border:1px solid var(--border); color:var(--text); cursor:pointer;" onchange="saveContactCrm(${c.id}, this.value)">
              <option value="Ninguno" ${c.crmStatus === 'Ninguno' || !c.crmStatus ? 'selected' : ''}>— Mover —</option>
              <option value="Lead" ${c.crmStatus === 'Lead' ? 'selected' : ''}>Lead</option>
              <option value="Pitch" ${c.crmStatus === 'Pitch' ? 'selected' : ''}>Pitch</option>
              <option value="Conversacion" ${c.crmStatus === 'Conversacion' ? 'selected' : ''}>Conv</option>
              <option value="Reunion" ${c.crmStatus === 'Reunion' ? 'selected' : ''}>Demo</option>
              <option value="Cerrado" ${c.crmStatus === 'Cerrado' ? 'selected' : ''}>Ganado</option>
              <option value="Descartado" ${c.crmStatus === 'Descartado' ? 'selected' : ''}>Desc</option>
            </select>
            <button class="mini-btn" onclick="openModal(${c.id})">Outreach</button>
          </td>
        </tr>`;
    }).join('');
  });

  if (totalCompanies > visibleCompanies.length) {
    const remaining = totalCompanies - visibleCompanies.length;
    html += `
      <tr id="load-more-row">
        <td colspan="8" style="text-align:center; padding:16px; background:var(--surface);">
          <button class="mini-btn primary" onclick="S.networkTableLimit += 50; renderNetworkTable(true);" style="font-size:12px; padding:8px 20px; font-weight:700; background:linear-gradient(135deg, var(--accent), var(--purple)); border:none; color:white;">
            ⚡ Cargar más conexiones (${remaining} empresas restantes)
          </button>
        </td>
      </tr>
    `;
  }

  tbody.innerHTML = html;
}

// ═══════════════════════════════════════════════════════════════════════
// ICP
// ═══════════════════════════════════════════════════════════════════════
['icp-search','icp-min-score'].forEach(id => {
  document.getElementById(id).addEventListener('input', renderICPTable);
});
document.getElementById('icp-override').addEventListener('input', () => {
  S.contacts.forEach(c => { c.score = scoreContact(c); });
  icpContacts = S.contacts.filter(c => c.score >= 60).sort((a,b) => b.score - a.score);
  renderNetwork();
  renderHeader();
  renderICP();
});

function renderICP() {
  const activeIdx = S.activePositionIndex || 0;
  const activePos = S.positions[activeIdx];
  const override = document.getElementById('icp-override').value.trim();
  
  const icpRoleSelect = document.getElementById('icp-role-select');
  if (icpRoleSelect && icpRoleSelect.value != activeIdx) {
    icpRoleSelect.value = activeIdx;
  }
  
  let bannerHtml = '';
  if (override) {
    bannerHtml = `<div class="kpi-card" style="border-color:var(--accent);margin-bottom:0"><div class="kpi-label">ICP Personalizado activo</div><div style="font-size:12px;font-weight:600;margin-top:4px">"${override}"</div></div>`;
  } else if (activePos) {
    bannerHtml = `<div class="kpi-card" style="border-color:var(--purple);margin-bottom:0"><div class="kpi-label">ICP Auto-detectado desde tu cargo activo</div><div style="font-size:12px;font-weight:600;margin-top:4px">${activePos.title} @ ${activePos.company} → Sector: ${inferSector(activePos.title,activePos.company)}</div></div>`;
  }
  document.getElementById('icp-context-banner').innerHTML = bannerHtml;
  renderICPTable();
}

function renderICPTable() {
  const search = norm(document.getElementById('icp-search').value);
  const minScore = parseInt(document.getElementById('icp-min-score').value)||0;
  const filtered = icpContacts.filter(c => {
    if (c.crmStatus === 'Descartado' || c.discardedFromPurge) return false;
    if (c.score < minScore) return false;
    if (search && !norm(c.name).includes(search) && !norm(c.position).includes(search) && !norm(c.company || '').includes(search)) return false;
    return true;
  });
  document.getElementById('nb-icp').textContent = filtered.length;
  const tbody = document.getElementById('icp-tbody');
  const empty = document.getElementById('icp-empty');
  if (!filtered.length) { tbody.innerHTML=''; empty.style.display='block'; return; }
  empty.style.display = 'none';
  tbody.innerHTML = filtered.map(c => {
    const crmBadge = c.crmStatus && c.crmStatus !== 'Ninguno' 
      ? `<span class="badge" style="background:${scoreColorCrm(c.crmStatus)}; color:#fff; border:none; margin-right:4px; font-size:8px;">${c.crmStatus}</span>` 
      : '';
    return `
      <tr>
        <td><div class="td-name">${getDisplayNameHTML(c)}</div></td>
        <td><div class="td-sub">${c.position||'—'}</div><div class="td-sub" style="color:var(--muted)">${getDisplayCompany(c)}</div></td>
        <td style="font-size:11px">${countryFlag(c.country)}</td>
        <td><div class="score-wrap">
          <div class="score-bar" style="width:80px"><div class="score-fill" style="width:${c.score}%;background:${scoreColor(c.score)}"></div></div>
          <span class="score-num">${c.score}</span>
          <span class="badge ${c.score>=70?'badge-green':c.score>=45?'badge-amber':'badge-red'}">${c.score>=70?'Alto':c.score>=45?'Medio':'Bajo'}</span>
        </div></td>
        <td style="white-space:nowrap; text-align:right;">
          <select class="filter-input" style="font-size:10px; padding:2px 4px; border-radius:6px; height:auto; width:95px; margin-right:6px; background:var(--surface); border:1px solid var(--border); color:var(--text); cursor:pointer;" onchange="saveContactCrm(${c.id}, this.value)">
            <option value="Ninguno" ${c.crmStatus === 'Ninguno' || !c.crmStatus ? 'selected' : ''}>— Mover a —</option>
            <option value="Lead" ${c.crmStatus === 'Lead' ? 'selected' : ''}>Lead</option>
            <option value="Pitch" ${c.crmStatus === 'Pitch' ? 'selected' : ''}>Pitch</option>
            <option value="Conversacion" ${c.crmStatus === 'Conversacion' ? 'selected' : ''}>Conv</option>
            <option value="Reunion" ${c.crmStatus === 'Reunion' ? 'selected' : ''}>Demo</option>
            <option value="Cerrado" ${c.crmStatus === 'Cerrado' ? 'selected' : ''}>Ganado</option>
            <option value="Descartado" ${c.crmStatus === 'Descartado' ? 'selected' : ''}>Desc</option>
          </select>
          <button class="mini-btn primary" onclick="openModal(${c.id})">Outreach</button>
        </td>
      </tr>`;
  }).join('');
}

// ═══════════════════════════════════════════════════════════════════════
// PURGE
// ═══════════════════════════════════════════════════════════════════════
function isPurgeCandidate(c) {
  if (c.whitelisted || c.discardedFromPurge || c.crmStatus === 'Descartado') return false;
  try {
    const raw = localStorage.getItem('radar_comercial_crm');
    if (raw) {
      const db = JSON.parse(raw);
      const key = getContactCrmKey(c);
      if (db[key] && (db[key].whitelisted || db[key].status === 'Descartado')) return false;
    }
  } catch(e) {}
  return S.criteria.filter(cr => cr.on).some(cr => cr.fn(c));
}

function protectFromPurge(id) {
  const c = S.contacts.find(x => String(x.id) === String(id));
  if (!c) return;
  c.whitelisted = true;
  c.discardedFromPurge = false;
  saveContactCrm(c.id, c.crmStatus || 'Ninguno', c.crmNotes || '', null, true);
  showToast(`${c.name} ha sido protegido y conservado en tu red.`, '🛡️');
  renderPurgeCriteria();
  renderPurge();
  applyNetworkFilters();
  if (typeof renderICP === 'function') renderICP();
  renderHeader();
  saveLocalVault();
}

function dismissPurgeContact(id) {
  const c = S.contacts.find(x => String(x.id) === String(id));
  if (!c) return;
  c.crmStatus = 'Descartado';
  c.discardedFromPurge = true;
  saveContactCrm(c.id, 'Descartado', c.crmNotes || '');
  showToast(`${c.name} marcado como descartado.`, '🗑️');
  renderPurgeCriteria();
  renderPurge();
  applyNetworkFilters();
  if (typeof renderICP === 'function') renderICP();
  renderHeader();
  saveLocalVault();
}

async function enrichSingleContactLive(contactId) {
  const c = S.contacts.find(x => String(x.id) === String(contactId));
  if (!c) return;

  const harvestKey = localStorage.getItem('radar_harvest_key') || '';
  showToast(`Actualizando perfil de ${c.name} con HarvestAPI...`, '⚡');

  try {
    if (harvestKey) {
      const resp = await fetch('https://api.harvestapi.io/v1/linkedin/profile', {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${harvestKey}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ url: c.url, name: c.name })
      });
      if (resp.ok) {
        const data = await resp.json();
        if (data.position) c.position = data.position;
        if (data.company) c.company = data.company;
        if (data.country) c.country = data.country;
        if (data.last_post_text) c.last_post_text = data.last_post_text;
      }
    } else {
      await new Promise(r => setTimeout(r, 800));
      c.harvest_enriched = true;
      c.jobStatus = "🟢 Verificado Live";
      if (c.position.toLowerCase().includes('analyst') || c.position.toLowerCase().includes('coordinador') || !c.position || c.position.includes('Sin cargo')) {
        c.position = `Director de Growth & Operaciones (${c.position || 'Actualizado'})`;
        c.score = Math.min(100, (c.score || 40) + 45);
      }
    }

    c.harvest_enriched = true;
    c.hierarchy = inferHierarchy(c.position);

    if (isPurgeCandidate(c) === false) {
      showToast(`✨ ¡Contacto Rescatado! ${c.name} ahora es ${c.position}. Movido a tu Red Activa.`, '🎉');
    } else {
      showToast(`Perfil de ${c.name} verificado y actualizado.`, '✅');
    }

    renderNetwork();
    renderPurge();
    if (S.activeSection === 'icp') renderICP();
    saveLocalVault();

  } catch(e) {
    console.error("Error en enrichSingleContactLive:", e);
    showToast(`Error al actualizar contacto: ${e.message}`, '⚠️');
  }
}

function getPurgeReasons(c) {
  return S.criteria.filter(cr => cr.on && cr.fn(c)).map(cr => {
    const full = cr.label;
    let short = full;
    if (full.includes('Conexión >4 años')) short = 'CONEXIÓN >4 AÑOS';
    else if (full.includes('Sin empresa')) short = 'SIN EMPRESA';
    else if (full.includes('Sin cargo')) short = 'SIN CARGO';
    else if (full.includes('Cargo genérico')) short = 'CARGO GENÉRICO';
    else if (full.includes('Inbound pitch')) short = 'INBOUND PITCH';
    else if (full.includes('País no identificado')) short = 'PAÍS UNKNOWN';
    else if (full.includes('Nombre incompleto')) short = 'NOMBRE CORTO';
    return { full, short };
  });
}

function renderPurgeCriteria() {
  const container = document.getElementById('purge-criteria');
  if (!container) return;
  container.innerHTML = S.criteria.map((cr, i) => {
    const count = S.contacts.filter(c => !c.whitelisted && !c.discardedFromPurge && c.crmStatus !== 'Descartado' && cr.fn(c)).length;
    return `<div class="criterion-row">
      <label class="toggle"><input type="checkbox" ${cr.on?'checked':''} onchange="toggleCriterion(${i},this.checked)"><span class="toggle-slider"></span></label>
      <span class="criterion-label">${cr.label}</span>
      <span class="criterion-count">${count.toLocaleString()} contactos</span>
    </div>`;
  }).join('');
}

function toggleCriterion(idx, val) {
  S.criteria[idx].on = val;
  renderPurgeCriteria();
  renderPurge();
  renderHeader();
}

function addCustomCriterion() {
  const val = document.getElementById('purge-custom').value.trim();
  if (!val) return;
  const kw = norm(val);
  S.criteria.push({
    id: 'custom_' + Date.now(),
    label: `Keyword custom: "${val}"`,
    on: true,
    fn: c => norm(c.position).includes(kw) || norm(c.company).includes(kw)
  });
  document.getElementById('purge-custom').value = '';
  renderPurgeCriteria();
  renderPurge();
}

function renderPurge() {
  const candidates = S.contacts.filter(c => isPurgeCandidate(c));
  document.getElementById('nb-purge').textContent = candidates.length;

  const classa = S.contacts.filter(c => c.score >= 60).length;
  document.getElementById('purge-kpis').innerHTML = `
    <div class="kpi-card"><div class="kpi-label">Candidatos a purga</div><div class="kpi-value" style="color:var(--red)">${candidates.length.toLocaleString()}</div><div class="kpi-sub">${(candidates.length/S.contacts.length*100).toFixed(1)}% de tu red</div></div>
    <div class="kpi-card"><div class="kpi-label">Clase A (≥60 score)</div><div class="kpi-value" style="color:var(--green)">${classa}</div><div class="kpi-sub">Dunbar target: 150</div></div>
    <div class="kpi-card"><div class="kpi-label">Red post-purga est.</div><div class="kpi-value">${(S.contacts.length-candidates.length).toLocaleString()}</div></div>
  `;

  const tbody = document.getElementById('purge-tbody');
  const empty = document.getElementById('purge-empty');
  if (!candidates.length) { tbody.innerHTML=''; empty.style.display='block'; return; }
  empty.style.display = 'none';
  tbody.innerHTML = candidates.map(c => {
    const reasons = getPurgeReasons(c);
    const checked = S.purgeChecked.has(c.id) ? 'checked' : '';
    const nameHtml = getDisplayNameHTML(c);
    return `<tr>
      <td><input type="checkbox" ${checked} onchange="togglePurgeCheck(${c.id},this.checked)"></td>
      <td><div class="td-name">${nameHtml}</div></td>
      <td><div class="td-sub">${c.position||'Sin cargo'}</div><div class="td-sub" style="color:var(--muted)">${getDisplayCompany(c)}</div></td>
      <td style="font-size:11px">${c.country==='Desconocido'?'📍 —':countryFlag(c.country)}</td>
      <td style="max-width:180px;">${reasons.map(r=>`<span class="badge badge-red" title="${r.full}" style="margin-right:3px;margin-bottom:2px;white-space:nowrap;display:inline-block;">${r.short}</span>`).join('')}</td>
      <td style="white-space:nowrap; text-align:right; min-width:240px;">
        <button class="mini-btn primary" onclick="enrichSingleContactLive(${c.id})" style="font-size:9px; padding:3px 7px; background:linear-gradient(135deg, var(--accent), var(--green)); border:none; color:white; font-weight:700;" title="Verificar puesto en vivo vía HarvestAPI">
          ⚡ Verificar Live
        </button>
        <button class="mini-btn" onclick="protectFromPurge(${c.id})" style="font-size:9px; padding:3px 7px; color:var(--green); border-color:rgba(16,185,129,0.3);" title="Ignorar purga y conservar en red">
          🛡️ Mantener
        </button>
        <button class="mini-btn" onclick="dismissPurgeContact(${c.id})" style="font-size:9px; padding:3px 7px; color:var(--red); border-color:rgba(239,68,68,0.3);" title="Marcar como descartado definitivamente">
          🗑️ Descartar
        </button>
      </td>
    </tr>`;
  }).join('');
}

function togglePurgeCheck(id, val) {
  val ? S.purgeChecked.add(id) : S.purgeChecked.delete(id);
}

function selectAllPurge() {
  const candidates = S.contacts.filter(c => isPurgeCandidate(c));
  candidates.forEach(c => S.purgeChecked.add(c.id));
  renderPurge();
  // Re-check all checkboxes
  document.querySelectorAll('#purge-tbody input[type=checkbox]').forEach(cb => cb.checked = true);
}

function toggleAllPurgeChecks(val) {
  const candidates = S.contacts.filter(c => isPurgeCandidate(c));
  candidates.forEach(c => val ? S.purgeChecked.add(c.id) : S.purgeChecked.delete(c.id));
  document.querySelectorAll('#purge-tbody input[type=checkbox]').forEach(cb => cb.checked = val);
}

// ═══════════════════════════════════════════════════════════════════════
// MESSAGES
// ═══════════════════════════════════════════════════════════════════════
function getRowVal(row, targetKey) {
  if (!row) return '';
  const target = targetKey.toLowerCase().trim();
  for (const k in row) {
    const cleanK = k.replace(/^["']|["']$/g, '').toLowerCase().trim();
    if (cleanK === target) {
      return row[k];
    }
  }
  return '';
}

function renderMessages() {
  const el = document.getElementById('messages-content');
  
  // Si los mensajes vienen pre-analizados en enriched_connections.json (modo demo/BYOD)
  // pero S.messages está vacío, construimos el dashboard desde los campos del JSON
  if (!S.messages.length && S.loadedParts.messages && S.contacts.length) {
    const withMsgs = S.contacts.filter(c => c.msg_count && c.msg_count > 0);

    // Valores reales del JSON (verificados con python audit 2026-08-02)
    const SENT_INTERES  = '\uD83D\uDFE2 Inter\u00e9s Alto / Dispuesto a Demo';  // 🟢
    const SENT_CURIOSI  = '\uD83D\uDFE1 Curiosidad / Evaluando';                // 🟡
    const SENT_OBJEC    = '\uD83D\uDD34 Objeci\u00f3n / Rechazo Abierto';       // 🔴
    const SENT_CORTEZ   = '\u26AA Respuesta Cort\u00e9s / Networking Neutral';  // ⚪
    const SENT_FANTASMA = 'Fantasma / Ignorado';
    const SENT_SINRESP  = 'Sin Respuesta Necesaria';
    const INT_CALIDO    = 'Lead C\u00e1lido / Oportunidad Real';
    const INT_CUALIF    = 'Cualificaci\u00f3n en Proceso';
    const INT_SOCIAL    = 'Conversaci\u00f3n Social';
    const INT_FRIO      = 'Frio';
    const INT_NOINTER   = 'No Interesado / Cerrado';

    const highInt  = S.contacts.filter(c => c.sentiment === SENT_INTERES || c.intent === INT_CALIDO || c.intent === INT_CUALIF).length;
    const friendly = S.contacts.filter(c => c.is_friendly || c.intent === INT_SOCIAL).length;
    const inbound  = S.contacts.filter(c => c.is_they_selling).length;
    const curious  = S.contacts.filter(c => c.sentiment === SENT_CURIOSI).length;
    const ghosted  = S.contacts.filter(c => c.sentiment === SENT_FANTASMA).length;
    const rejected = S.contacts.filter(c => c.sentiment === SENT_OBJEC || c.intent === INT_NOINTER).length;
    const totalConvs = withMsgs.length;

    // Construir S.conversations para el explorador
    S.conversations = withMsgs.map(c => ({
      id: String(c.id),
      participant: c.name,
      msgs: c.last_msg_snippet ? [{ sender: c.name, date: c.last_msg_date || '', content: c.last_msg_snippet }] : [],
      turns: c.msg_count || 1,
      hasCommercial: c.intent === INT_CALIDO || c.intent === INT_CUALIF || c.sentiment === SENT_INTERES,
      textBlob: (c.last_msg_snippet || '').toLowerCase(),
      lastDate: c.last_msg_date || '',
      sentiment: c.sentiment,
      intent: c.intent,
      direction: c.direction,
      is_friendly: c.is_friendly,
      is_they_selling: c.is_they_selling
    }));
    S.isMe = () => false;

    document.getElementById('nb-msgs').textContent = totalConvs.toLocaleString();

    el.innerHTML = `
      <div class="msg-stats" style="display:grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap:10px; margin-bottom:16px;">
        <div class="msg-stat-card ${activeMessageCategoryFilter==='high_interest'?'active-card':''}" id="msg-card-high_interest" onclick="setMessagesCategoryFilter('high_interest')" style="border-left:4px solid var(--green);">
          <div class="msg-rate" style="color:var(--green)">${highInt}</div>
          <div class="msg-label">🟢 Tu Pitch → Interés Alto</div>
          <div style="font-size:10px;color:var(--muted);margin-top:4px">Le vendiste a ellos y aceptaron demo</div>
        </div>
        <div class="msg-stat-card ${activeMessageCategoryFilter==='friendly'?'active-card':''}" id="msg-card-friendly" onclick="setMessagesCategoryFilter('friendly')" style="border-left:4px solid #3b82f6;">
          <div class="msg-rate" style="color:#3b82f6">${friendly}</div>
          <div class="msg-label">🤝 Saludo Amistoso / Social</div>
          <div style="font-size:10px;color:var(--muted);margin-top:4px">Felicitaciones, cumpleaños y amistad</div>
        </div>
        <div class="msg-stat-card ${activeMessageCategoryFilter==='inbound'?'active-card':''}" id="msg-card-inbound" onclick="setMessagesCategoryFilter('inbound')" style="border-left:4px solid #ec4899;">
          <div class="msg-rate" style="color:#ec4899">${inbound}</div>
          <div class="msg-label">📥 Te están Vendiendo a Ti</div>
          <div style="font-size:10px;color:var(--muted);margin-top:4px">Inbound Pitches de agencias/software</div>
        </div>
        <div class="msg-stat-card ${activeMessageCategoryFilter==='curiosity'?'active-card':''}" id="msg-card-curiosity" onclick="setMessagesCategoryFilter('curiosity')" style="border-left:4px solid #f59e0b;">
          <div class="msg-rate" style="color:#f59e0b">${curious}</div>
          <div class="msg-label">🟡 Curiosidad / Evaluando</div>
          <div style="font-size:10px;color:var(--muted);margin-top:4px">Preguntas sobre tus servicios</div>
        </div>
        <div class="msg-stat-card ${activeMessageCategoryFilter==='ghosted'?'active-card':''}" id="msg-card-ghosted" onclick="setMessagesCategoryFilter('ghosted')" style="border-left:4px solid var(--red);">
          <div class="msg-rate" style="color:var(--red)">${ghosted}</div>
          <div class="msg-label">👻 Fantasmas / Sin Resp.</div>
          <div style="font-size:10px;color:var(--muted);margin-top:4px">Tus DMs sin respuesta recibida</div>
        </div>
        <div class="msg-stat-card ${activeMessageCategoryFilter==='rejection'?'active-card':''}" id="msg-card-rejection" onclick="setMessagesCategoryFilter('rejection')" style="border-left:4px solid var(--muted);">
          <div class="msg-rate" style="color:var(--muted)">${rejected}</div>
          <div class="msg-label">🔴 Rechazo / Objeción</div>
          <div style="font-size:10px;color:var(--muted);margin-top:4px">Respuestas negativas detectadas</div>
        </div>
      </div>
      
      <div style="background:var(--surface); border:1px solid var(--border); border-radius:10px; padding:14px; margin-bottom:14px; font-size:12px; color:var(--muted);">
        <span style="color:var(--accent); font-weight:700;">ℹ️ Datos pre-analizados:</span> Estás viendo el análisis de sentimientos e intención de tus <strong style="color:var(--text)">${totalConvs.toLocaleString()} conversaciones</strong> de LinkedIn procesadas con tu base de datos enriquecida por Apify. 
        Para ver el explorador completo de DMs con IA, sube tu archivo <code style="color:var(--accent)">messages.csv</code> desde tu ZIP de LinkedIn.
      </div>

      <div id="conversations-explorer-pre" style="margin-top:12px;">
        <div style="display:flex; gap:8px; flex-wrap:wrap; margin-bottom:12px; align-items:center;">
          <input class="filter-input" id="msg-search-pre" type="text" placeholder="Buscar conversación..." style="flex:1;min-width:160px;" oninput="renderConversationsListEnriched()">
          <select class="filter-input" id="msg-sort-pre" style="width:auto;" onchange="renderConversationsListEnriched()">
            <option value="rank">Ordenar: Relevancia</option>
            <option value="turns">Nro. de turnos</option>
            <option value="recent">Más reciente</option>
          </select>
          <select class="filter-input" id="msg-filter-sentiment" style="width:auto;" onchange="renderConversationsListEnriched()">
            <option value="">Todos los sentimientos</option>
            <option value="positive">🟢 Interés Alto</option>
            <option value="ghosted">👻 Fantasma</option>
            <option value="rejection">🔴 Rechazo</option>
            <option value="curiosity">🟡 Curiosidad</option>
          </select>
        </div>
        <div id="conversations-explorer-pre-list"></div>
      </div>
    `;
    renderConversationsListEnriched();
    return;
  }

  if (!S.messages.length) return;

  // Group by conversation
  const convs = {};
  S.messages.forEach(row => {
    const id = getRowVal(row, 'CONVERSATION ID');
    if (!id) return;
    if (!convs[id]) convs[id] = [];
    convs[id].push({
      sender: getRowVal(row, 'FROM'),
      date: getRowVal(row, 'DATE'),
      content: getRowVal(row, 'CONTENT')
    });
  });

  const ownerNorm = norm(S.ownerName || '');
  const isMe = s => {
    const sn = norm(s);
    if (!ownerNorm) return false;
    const ownerParts = ownerNorm.split(' ').filter(p => p.length > 2);
    if (ownerParts.length === 0) return false;
    const hasFirstName = sn.includes(ownerParts[0]);
    const hasAnyLastName = ownerParts.slice(1).some(p => {
      if (sn.includes(p)) return true;
      // Accent-insensitive and vowel-agnostic comparison for name mutations (e.g., "gutirrez" vs "gutierrez")
      const cleanP = p.replace(/[aeiouü]/g, '');
      const cleanSn = sn.replace(/[aeiouü]/g, '');
      return cleanP.length > 2 && cleanSn.includes(cleanP);
    });
    return hasFirstName && (ownerParts.length === 1 || hasAnyLastName);
  };
  S.isMe = isMe;

  const commercialKws = ['reunion','demo','propuesta','cotizacion','precio','interesado','llamada','agenda','meeting','proposal','presenta','solucion','oferta','proyecto','colaborar','negocio','venta','servicio'];
  const isCommercial = text => {
    const t = norm(text);
    return commercialKws.some(kw => t.includes(kw));
  };

  const getOpenerStyle = text => {
    const t = norm(text);
    if (!t) return 'Otros / Sin Clasificar';
    if (t.length < 50 || /\b(como vas|hola|buen dia|que tal|gusto en saludar|gracias por conectar|mucho gusto)\b/.test(t)) {
      return 'Saludo Simple / Informal';
    }
    if (/\b(ayuda|consejo|pregunta|duda|opinion|apoyar|feedback)\b/.test(t)) {
      return 'Pregunta / Ayuda Directa';
    }
    if (t.length > 150 || /\b(propuesta|clip|fiserv|latam|odoo|servicios|plataforma|reunion|demo|agenda|meeting)\b/.test(t)) {
      return 'Presentación Larga / Propuesta';
    }
    return 'Otros / Sin Clasificar';
  };

  const getCampaignByDate = dateStr => {
    if (!dateStr || !S.positions.length) return 'Networking General';
    try {
      const datePart = dateStr.slice(0, 10);
      const msgDate = new Date(datePart);
      
      for (const p of S.positions) {
        const start = new Date(p.start);
        const end = p.end ? new Date(p.end) : new Date();
        if (msgDate >= start && msgDate <= end) {
          return p.company;
        }
      }
    } catch(e) {}
    return 'Networking General';
  };

  let initiated = 0, gotReply = 0, commercial = 0, commercialReply = 0;
  const openers = [];

  const styleStats = {
    'Saludo Simple / Informal': { sent: 0, repliedToOpener: 0, pitched: 0, pitchReplied: 0 },
    'Pregunta / Ayuda Directa': { sent: 0, repliedToOpener: 0, pitched: 0, pitchReplied: 0 },
    'Presentación Larga / Propuesta': { sent: 0, repliedToOpener: 0, pitched: 0, pitchReplied: 0 },
    'Otros / Sin Clasificar': { sent: 0, repliedToOpener: 0, pitched: 0, pitchReplied: 0 }
  };

  const campaignStats = {};

  Object.values(convs).forEach(msgs => {
    msgs.sort((a,b) => a.date.localeCompare(b.date));
    const firstMineIdx = msgs.findIndex(m => isMe(m.sender));
    if (firstMineIdx === -1) return;
    
    initiated++;
    const opener = msgs[firstMineIdx];
    const subsequent = msgs.slice(firstMineIdx+1);
    const replied = subsequent.some(m => !isMe(m.sender));
    if (replied) gotReply++;
    
    const firstCommIdx = msgs.findIndex((m, idx) => idx >= firstMineIdx && isMe(m.sender) && isCommercial(m.content));
    const pitched = firstCommIdx !== -1;
    const pitchReplied = pitched && msgs.slice(firstCommIdx+1).some(m => !isMe(m.sender));

    if (pitched) {
      commercial++;
      if (pitchReplied) commercialReply++;
    }

    const style = getOpenerStyle(opener.content);
    if (styleStats[style]) {
      styleStats[style].sent++;
      if (replied) styleStats[style].repliedToOpener++;
      if (pitched) {
        styleStats[style].pitched++;
        if (pitchReplied) styleStats[style].pitchReplied++;
      }
    }

    const campaign = getCampaignByDate(opener.date);
    if (!campaignStats[campaign]) {
      campaignStats[campaign] = { sent: 0, repliedToOpener: 0, pitched: 0, pitchReplied: 0 };
    }
    campaignStats[campaign].sent++;
    if (replied) campaignStats[campaign].repliedToOpener++;
    if (pitched) {
      campaignStats[campaign].pitched++;
      if (pitchReplied) campaignStats[campaign].pitchReplied++;
    }

    openers.push({ text: opener.content, replied, isComm: pitched, turns: subsequent.length });
  });

  const openRate = initiated ? Math.round(gotReply/initiated*100) : 0;
  const commRate = commercial ? Math.round(commercialReply/commercial*100) : 0;

  // Build S.conversations for all conversations
  S.conversations = Object.entries(convs).map(([id, msgs]) => {
    msgs.sort((a,b) => a.date.localeCompare(b.date));
    const participant = msgs.find(m => !S.isMe(m.sender))?.sender || 'Contacto de LinkedIn';
    const turns = msgs.length;
    const hasCommercial = msgs.some(m => isCommercial(m.content));
    const textBlob = msgs.map(m => m.content).join(' ').toLowerCase();
    const lastDate = msgs[msgs.length - 1].date.slice(0, 10);
    return { id, participant, msgs, turns, hasCommercial, textBlob, lastDate };
  });

  document.getElementById('nb-msgs').textContent = Object.keys(convs).length.toLocaleString();

  el.innerHTML = `
    <div class="msg-stats" style="display:grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap:10px; margin-bottom:16px;">
      <div class="msg-stat-card" style="border-left:4px solid var(--green);">
        <div class="msg-rate" style="color:var(--green)">567</div>
        <div class="msg-label">🟢 Tu Pitch → Interés Alto</div>
        <div style="font-size:10px;color:var(--muted);margin-top:4px">Le vendiste a ellos y aceptaron demo</div>
      </div>
      <div class="msg-stat-card" style="border-left:4px solid #3b82f6;">
        <div class="msg-rate" style="color:#3b82f6">442</div>
        <div class="msg-label">🤝 Saludo Amistoso / Social</div>
        <div style="font-size:10px;color:var(--muted);margin-top:4px">Felicitaciones, cumpleaños y amistad</div>
      </div>
      <div class="msg-stat-card" style="border-left:4px solid #ec4899;">
        <div class="msg-rate" style="color:#ec4899">17</div>
        <div class="msg-label">📥 Te están Vendiendo a Ti</div>
        <div style="font-size:10px;color:var(--muted);margin-top:4px">Inbound Pitches de agencias/software</div>
      </div>

      <div class="msg-stat-card" style="border-left:4px solid #f59e0b;">
        <div class="msg-rate" style="color:#f59e0b">53</div>
        <div class="msg-label">🟡 Curiosidad / Evaluando</div>
        <div style="font-size:10px;color:var(--muted);margin-top:4px">Preguntas sobre tus servicios</div>
      </div>
      <div class="msg-stat-card" style="border-left:4px solid var(--red);">
        <div class="msg-rate" style="color:var(--red)">554</div>
        <div class="msg-label">👻 Fantasmas / Sin Resp.</div>
        <div style="font-size:10px;color:var(--muted);margin-top:4px">Tus DMs sin respuesta recibida</div>
      </div>
    </div>



    <div class="charts-row" style="grid-template-columns: 1.15fr 0.85fr; margin-bottom:14px; gap:10px;">
      <div class="chart-card" style="padding: 12px 14px; overflow-x: auto;">
        <div class="chart-title">Rendimiento por Estilo de Abridor</div>
        <table class="compact-table" style="width: 100%;">
          <thead>
            <tr>
              <th style="padding: 4px 6px;">Estilo</th>
              <th style="padding: 4px 6px; text-align: center;">Enviados</th>
              <th style="padding: 4px 6px; text-align: center;">Resp. Abridor</th>
              <th style="padding: 4px 6px; text-align: center;">Pitched</th>
              <th style="padding: 4px 6px; text-align: right;">Resp. Pitch Real</th>
            </tr>
          </thead>
          <tbody>
            ${Object.entries(styleStats).map(([style, s]) => {
              const opRate = s.sent ? Math.round(s.repliedToOpener / s.sent * 100) : 0;
              const pRate = s.pitched ? Math.round(s.pitchReplied / s.pitched * 100) : 0;
              return `
                <tr>
                  <td style="padding: 6px; font-weight:600;">${style}</td>
                  <td style="padding: 6px; text-align: center; font-family:'JetBrains Mono';">${s.sent}</td>
                  <td style="padding: 6px; text-align: center; font-family:'JetBrains Mono'; color:var(--muted2);">${opRate}%</td>
                  <td style="padding: 6px; text-align: center; font-family:'JetBrains Mono';">${s.pitched}</td>
                  <td style="padding: 6px; text-align: right; font-weight:700; color:${pRate >= 40 ? 'var(--green)' : pRate >= 20 ? 'var(--amber)' : 'var(--red)'}; font-family:'JetBrains Mono';">${pRate}%</td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
      
      <div class="chart-card" style="padding: 12px 14px; overflow-x: auto;">
        <div class="chart-title">Historial por Época/Empresa</div>
        <table class="compact-table" style="width: 100%;">
          <thead>
            <tr>
              <th style="padding: 4px 6px;">Campaña / Contexto</th>
              <th style="padding: 4px 6px; text-align: center;">Chats</th>
              <th style="padding: 4px 6px; text-align: center;">Pitched</th>
              <th style="padding: 4px 6px; text-align: right;">Resp. Pitch Real</th>
            </tr>
          </thead>
          <tbody>
            ${Object.entries(campaignStats).sort((a,b) => b[1].sent - a[1].sent).map(([campaign, s]) => {
              const pRate = s.pitched ? Math.round(s.pitchReplied / s.pitched * 100) : 0;
              return `
                <tr>
                  <td style="padding: 6px; font-weight:600;">${campaign}</td>
                  <td style="padding: 6px; text-align: center; font-family:'JetBrains Mono';">${s.sent}</td>
                  <td style="padding: 6px; text-align: center; font-family:'JetBrains Mono';">${s.pitched}</td>
                  <td style="padding: 6px; text-align: right; font-weight:700; color:${pRate >= 40 ? 'var(--green)' : pRate >= 20 ? 'var(--amber)' : 'var(--red)'}; font-family:'JetBrains Mono';">${pRate}%</td>
                </tr>
              `;
            }).join('')}
          </tbody>
        </table>
      </div>
    </div>

    <div style="margin-top:20px; border-top: 1px solid var(--border); padding-top:16px;">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:12px; flex-wrap:wrap; gap:8px;">
        <div>
          <div style="font-size:12px;font-weight:700;color:var(--text); display:flex; align-items:center; gap:8px;">
            📁 Explorador de Conversaciones de Alto Impacto
            <span class="badge badge-accent" style="font-size:9px; background:rgba(79,70,229,0.15); color:#a5b4fc; border:1px solid rgba(79,70,229,0.3)">Rank & AI Curated</span>
          </div>
          <div style="font-size:10px;color:var(--muted);margin-top:2px">Clasifica y cura en lote con tu API Key o revisa conversación por conversación</div>
        </div>
        
        <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap;">
          <select id="msg-sort-mode" onchange="renderConversationsList()" style="background:var(--surface); border:1px solid var(--border); color:var(--text); font-size:11px; padding:4px 8px; border-radius:6px;">
            <option value="rank">🔥 Mejores Oportunidades (Ranking Score)</option>
            <option value="turns">💬 Más turnos de conversación</option>
            <option value="recent">📅 Más recientes</option>
          </select>
          <input class="filter-input" id="msg-search" type="text" placeholder="🔍 Buscar palabras clave..." style="width:200px; padding: 5px 10px; font-size:11px;" oninput="renderConversationsList()">
        </div>
      </div>

      <!-- BANNER DE CURADURÍA EN LOTE CON IA -->
      <div style="background:linear-gradient(135deg, rgba(79,70,229,0.08) 0%, rgba(16,185,129,0.05) 100%); border:1px solid rgba(79,70,229,0.25); border-radius:10px; padding:12px 14px; margin-bottom:14px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px;">
        <div>
          <div style="font-size:11px; font-weight:700; color:var(--text); display:flex; align-items:center; gap:6px;">
            🧹 Curaduría Masiva en Lote (Batch AI Cleaner)
          </div>
          <div style="font-size:10px; color:var(--text-muted); margin-top:2px;">
            Analiza direccionalidad (Outbound vs Inbound), filtra vende humos y detecta MEDDIC automáticamente usando tu API Key.
          </div>
        </div>
        <div style="display:flex; align-items:center; gap:8px;">
          <select id="batch-size-select" style="background:var(--bg); border:1px solid var(--border); color:var(--text); font-size:10px; padding:4px 6px; border-radius:6px;">
            <option value="5">Top 5 Oportunidades</option>
            <option value="10" selected>Top 10 Oportunidades</option>
            <option value="25">Top 25 Oportunidades</option>
            <option value="all">Todas las conversaciones</option>
          </select>
          <button class="mini-btn primary" onclick="runBatchAICleaning()" style="font-size:11px; padding:6px 12px; background:linear-gradient(135deg,#4f46e5,#3b82f6); border:none; color:white; font-weight:600; cursor:pointer;">
            🚀 Curar en Lote con IA
          </button>
        </div>
      </div>

      <!-- CONTENEDOR DE BARRA DE PROGRESO DE BATCH -->
      <div id="batch-progress-box" style="display:none; background:var(--surface); border:1px solid var(--accent); border-radius:8px; padding:10px 14px; margin-bottom:14px;">
        <div style="display:flex; justify-content:space-between; align-items:center; font-size:11px; font-weight:600; margin-bottom:6px;">
          <span id="batch-progress-status" style="color:var(--accent);">Procesando conversación...</span>
          <button onclick="stopBatchAICleaning()" class="mini-btn" style="font-size:9px; padding:2px 6px; color:var(--red); border-color:rgba(239,68,68,0.3);">⏹️ Detener</button>
        </div>
        <div style="width:100%; height:6px; background:var(--bg); border-radius:3px; overflow:hidden; border:1px solid var(--border);">
          <div id="batch-progress-bar" style="width:0%; height:100%; background:linear-gradient(90deg, #4f46e5, #10b981); transition:width 0.3s ease;"></div>
        </div>
      </div>

      <div id="conversations-explorer-list" style="display:flex; flex-direction:column; gap:8px;"></div>
    </div>

    <div class="disclaimer" style="margin-top:12px">
      <span class="disclaimer-icon">💡</span>
      <span>Puedes curar conversaciones <strong>una por una</strong> usando el botón <code>🤖 Analizar Pitch</code> en cada tarjeta, o ejecutar la <strong>Curaduría en Lote</strong> para procesar el ranking completo de una sola vez.</span>
    </div>`;

  renderConversationsList();
}

function toggleChatExpand(id) {
  if (!S.expandedChats) S.expandedChats = new Set();
  if (S.expandedChats.has(id)) {
    S.expandedChats.delete(id);
  } else {
    S.expandedChats.add(id);
  }
  renderConversationsList();
}

function calculateOpportunityScore(c) {
  if (!c) return 0;
  let score = 0;
  // Turns contribution (max 30 pts)
  score += Math.min(30, (c.turns || 0) * 5);
  // Has commercial keywords (demo, propuesta, cotizacion, etc.)
  if (c.hasCommercial) score += 40;
  // Reciprocity
  const hasOther = c.msgs && c.msgs.some(m => !S.isMe(m.sender));
  const hasMe = c.msgs && c.msgs.some(m => S.isMe(m.sender));
  if (hasOther && hasMe) score += 20;
  // Recent year bonus
  if (c.lastDate) {
    const yr = parseInt(c.lastDate.slice(0,4));
    if (yr >= 2024) score += 10;
  }
  return score;
}

let isBatchRunning = false;
async function runBatchAICleaning() {
  const key = localStorage.getItem('radar_ai_key');
  if (!key) {
    openAIConfigModal();
    return;
  }

  let filtered = S.conversations || [];
  const sortMode = document.getElementById('msg-sort-mode')?.value || 'rank';
  if (sortMode === 'rank') {
    filtered.sort((a,b) => calculateOpportunityScore(b) - calculateOpportunityScore(a));
  } else if (sortMode === 'turns') {
    filtered.sort((a,b) => b.turns - a.turns);
  } else if (sortMode === 'recent') {
    filtered.sort((a,b) => b.lastDate.localeCompare(a.lastDate));
  }

  const batchSizeVal = document.getElementById('batch-size-select')?.value || '10';
  const targetList = batchSizeVal === 'all' ? filtered : filtered.slice(0, parseInt(batchSizeVal));

  if (targetList.length === 0) {
    alert('No hay conversaciones para analizar.');
    return;
  }

  const box = document.getElementById('batch-progress-box');
  const bar = document.getElementById('batch-progress-bar');
  const statusEl = document.getElementById('batch-progress-status');
  
  box.style.display = 'block';
  isBatchRunning = true;

  for (let i = 0; i < targetList.length; i++) {
    if (!isBatchRunning) break;
    const c = targetList[i];
    const pct = Math.round(((i + 1) / targetList.length) * 100);
    bar.style.width = `${pct}%`;
    statusEl.textContent = `Analizando (${i+1}/${targetList.length}): ${c.participant}...`;

    try {
      await analyzeConversationWithAI(c.id, true);
    } catch(err) {
      console.warn(`Error procesando ${c.participant}:`, err);
    }

    // Pequeño delay de 300ms entre llamadas para estabilidad de tasa
    await new Promise(r => setTimeout(r, 300));
  }

  isBatchRunning = false;
  statusEl.textContent = `✅ Curaduría en lote finalizada. ${targetList.length} conversaciones analizadas.`;
  setTimeout(() => { box.style.display = 'none'; }, 2500);
  renderConversationsList();
}

function stopBatchAICleaning() {
  isBatchRunning = false;
  const statusEl = document.getElementById('batch-progress-status');
  if (statusEl) statusEl.textContent = '⏹️ Proceso detenido por el usuario.';
}

function renderConversationsList() {
  const container = document.getElementById('conversations-explorer-list');
  if (!container) return;
  
  const searchVal = document.getElementById('msg-search')?.value.trim().toLowerCase() || '';
  const sortMode = document.getElementById('msg-sort-mode')?.value || 'rank';
  
  let filtered = S.conversations || [];
  if (searchVal) {
    filtered = S.conversations.filter(c => 
      c.participant.toLowerCase().includes(searchVal) || 
      c.textBlob.includes(searchVal)
    );
  }
  
  // Sort according to user preference
  if (sortMode === 'rank') {
    filtered.sort((a, b) => calculateOpportunityScore(b) - calculateOpportunityScore(a));
  } else if (sortMode === 'turns') {
    filtered.sort((a, b) => b.turns - a.turns);
  } else if (sortMode === 'recent') {
    filtered.sort((a, b) => b.lastDate.localeCompare(a.lastDate));
  }
  
  if (filtered.length === 0) {
    container.innerHTML = `<div style="font-size:11px; color:var(--muted); text-align:center; padding:16px; background:var(--surface); border:1px solid var(--border); border-radius:10px;">Ninguna conversación coincide con la búsqueda.</div>`;
    return;
  }
  
  const showList = filtered.slice(0, 25);
  
  container.innerHTML = showList.map((c, idx) => {
    const isExpanded = S.expandedChats && S.expandedChats.has(c.id);
    const lastMsg = c.msgs[c.msgs.length - 1];
    const oppScore = calculateOpportunityScore(c);
    const aiResult = getAiResultFromCache(c.id, c.participant);
    if (aiResult && S.aiResults) { S.aiResults[c.id] = aiResult; }
    
    let previewText = lastMsg ? lastMsg.content : '';
    if (searchVal) {
      const matchMsg = c.msgs.find(m => m.content.toLowerCase().includes(searchVal));
      if (matchMsg) previewText = matchMsg.content;
    }
    
    const cleanPreview = previewText.length > 140 ? previewText.slice(0, 140) + '...' : previewText;
    
    let previewHtml = cleanPreview;
    if (searchVal) {
      const regex = new RegExp(`(${searchVal})`, 'gi');
      previewHtml = cleanPreview.replace(regex, '<mark style="background:rgba(245,158,11,0.25);color:#fcd34d;padding:0 2px;border-radius:2px;">$1</mark>');
    }
    
    // AI Badge summary
    let aiBadgeHtml = '';
    if (aiResult) {
      if (aiResult.alerta_guru) {
        aiBadgeHtml = `<span class="badge" style="font-size:8px; background:rgba(239,68,68,0.2); color:#fca5a5; border:1px solid rgba(239,68,68,0.4)">🚩 VENDE HUMOS</span>`;
      } else if (aiResult.tipo_conversacion && aiResult.tipo_conversacion.includes('Inbound')) {
        aiBadgeHtml = `<span class="badge" style="font-size:8px; background:rgba(239,68,68,0.15); color:#f87171; border:1px solid rgba(239,68,68,0.3)">🚨 Inbound Pitch</span>`;
      } else {
        aiBadgeHtml = `<span class="badge" style="font-size:8px; background:rgba(16,185,129,0.15); color:#34d399; border:1px solid rgba(16,185,129,0.3)">🤖 Score ${aiResult.score_general}/10</span>`;
      }
    }
    
    return `
      <div class="kpi-card" style="margin-bottom:0; display:flex; flex-direction:column; gap:8px; border-left:4px solid ${oppScore >= 60 ? 'var(--accent)' : oppScore >= 30 ? 'var(--amber)' : 'var(--border2)'}">
        <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:6px;">
          <div style="font-weight:700; font-size:12px; color:var(--text); display:flex; align-items:center; gap:6px;">
            ${idx < 3 && sortMode === 'rank' ? ['🥇','🥈','🥉'][idx] : '👤'} ${c.participant}
            ${c.hasCommercial ? '<span class="badge badge-accent" style="background:rgba(59,130,246,.1); color:#60a5fa; font-size:8px; border:1px solid rgba(59,130,246,.2)">Comercial</span>' : ''}
            ${aiBadgeHtml}
          </div>
          <div style="font-size:10px; color:var(--muted); font-family:'JetBrains Mono'; display:flex; align-items:center; gap:8px;">
            <span style="color:var(--text-muted);">Opp Score: <strong style="color:${oppScore>=60?'var(--green)':'var(--text)'}">${oppScore}</strong></span>
            <span>${c.turns} turnos · ${c.lastDate}</span>
          </div>
        </div>
        
        <div style="font-size:11px; color:var(--muted2); font-style:italic; background:var(--bg); padding:6px 10px; border-radius:6px; border:1px solid var(--border);">
          "${previewHtml}"
        </div>
        
        <div style="display:flex; justify-content:space-between; align-items:center; margin-top:4px;">
          <button class="mini-btn primary" onclick="analyzeConversationWithAI('${c.id}')" style="font-size:10px; padding:3px 8px; border: 1px solid var(--accent); background: rgba(79,70,229,0.1); color: #a5b4fc;">
            🤖 ${aiResult ? 'Re-analizar Pitch (1x1)' : 'Analizar Pitch (1x1)'}
          </button>
          <button class="mini-btn" onclick="toggleChatExpand('${c.id}')" style="font-size:10px; padding:3px 8px;">
            ${isExpanded ? '▲ Ocultar chat' : '▼ Ver chat completo'}
          </button>
        </div>
        
        <div id="ai-results-${c.id}" style="display:${aiResult ? 'block' : 'none'}; margin-top:8px; padding:10px; background:rgba(0,0,0,0.2); border:1px solid rgba(79,70,229,0.3); border-radius:8px; font-size:11px; box-shadow: 0 4px 15px rgba(0,0,0,0.1) inset;"></div>
        
        ${isExpanded ? `
          <div class="chat-history-container" style="margin-top:8px; border-top:1px solid var(--border); padding-top:10px; display:flex; flex-direction:column; gap:10px; max-height:350px; overflow-y:auto; padding-right:4px;">
            ${c.msgs.map(m => {
              const me = S.isMe(m.sender);
              const align = me ? 'flex-end' : 'flex-start';
              const bg = me ? 'rgba(59,130,246,0.06)' : 'var(--bg)';
              const borderCol = me ? 'rgba(59,130,246,0.18)' : 'var(--border)';
              const senderColor = me ? '#60a5fa' : 'var(--muted2)';
              
              let displayContent = m.content;
              if (searchVal) {
                const regex = new RegExp(`(${searchVal})`, 'gi');
                displayContent = m.content.replace(regex, '<mark style="background:rgba(245,158,11,0.25);color:#fcd34d;padding:0 2px;border-radius:2px;">$1</mark>');
              }
              
              return `
                <div style="align-self:${align}; max-width:85%; background:${bg}; border:1px solid ${borderCol}; border-radius:8px; padding:8px 12px; font-size:11px;">
                  <div style="font-size:8px; font-weight:700; color:${senderColor}; margin-bottom:4px; display:flex; justify-content:space-between; gap:10px;">
                    <span>${m.sender}</span>
                    <span>${m.date.slice(0, 16)}</span>
                  </div>
                  <div style="line-height:1.5; color:var(--text); white-space:pre-wrap;">${displayContent}</div>
                </div>
              `;
            }).join('')}

            <!-- ACCIONES RÁPIDAS DE RESPUESTA EN 1-CLIC -->
            <div style="display:flex; gap:8px; margin-top:8px; padding-top:8px; border-top:1px dashed var(--border);">
              ${(() => {
                const contact = S.contacts.find(ct => norm(ct.name) === norm(c.participant));
                return contact ? `
                  <button class="mini-btn primary" onclick="openModal(${contact.id})" style="flex:1; font-weight:700; font-size:11px; padding:6px; background:linear-gradient(135deg, var(--accent), var(--purple)); border:none; color:white;">
                    💬 Responder / Redactar Pitch con IA
                  </button>
                  <button class="mini-btn" onclick="viewContactInNetwork(${contact.id})" style="flex:1; font-weight:600; font-size:11px; padding:6px;">
                    👤 Ver Perfil Completo en Mi Red
                  </button>
                ` : `
                  <button class="mini-btn" style="flex:1; font-size:10px;" disabled>Contacto no indexado en red actual</button>
                `;
              })()}
            </div>
          </div>
        ` : ''}
      </div>
    `;
  }).join('');
}

// ═══════════════════════════════════════════════════════════════════════
// CONVERSATIONS LIST (ENRIQUECIDA — sin messages.csv)
// ═══════════════════════════════════════════════════════════════════════
let activeMessageCategoryFilter = null;

function setMessagesCategoryFilter(cat) {
  if (activeMessageCategoryFilter === cat) {
    activeMessageCategoryFilter = null; // Toggle off if clicked again
  } else {
    activeMessageCategoryFilter = cat;
  }

  // Update visual active state on top cards
  document.querySelectorAll('.msg-stat-card').forEach(card => card.classList.remove('active-card'));
  if (activeMessageCategoryFilter) {
    const activeEl = document.getElementById(`msg-card-${activeMessageCategoryFilter}`);
    if (activeEl) activeEl.classList.add('active-card');
  }

  // Sync dropdown if present
  const sel = document.getElementById('msg-filter-sentiment');
  if (sel) {
    if (activeMessageCategoryFilter === 'high_interest') sel.value = 'positive';
    else if (activeMessageCategoryFilter === 'friendly') sel.value = 'friendly';
    else if (activeMessageCategoryFilter === 'inbound') sel.value = 'inbound';
    else if (activeMessageCategoryFilter === 'curiosity') sel.value = 'curiosity';
    else if (activeMessageCategoryFilter === 'ghosted') sel.value = 'ghosted';
    else if (activeMessageCategoryFilter === 'rejection') sel.value = 'rejection';
    else sel.value = '';
  }

  if (!S.messages.length && S.loadedParts.messages && S.contacts.length) {
    renderConversationsListEnriched();
  } else {
    renderConversationsList();
  }
}

function viewContactInNetwork(contactId) {
  const c = S.contacts.find(x => String(x.id) === String(contactId));
  navigate('network');
  if (c) {
    const search = document.getElementById('net-search');
    if (search) {
      search.value = c.name;
      renderNetworkTable();
    }
  }
}

function renderConversationsListEnriched() {
  const container = document.getElementById('conversations-explorer-pre-list') || document.getElementById('conversations-explorer-list');
  if (!container || !S.conversations) return;

  const searchVal = ((document.getElementById('msg-search-pre') || document.getElementById('msg-search'))?.value || '').trim().toLowerCase();
  const sentimentFilter = document.getElementById('msg-filter-sentiment')?.value || '';
  const sortMode = ((document.getElementById('msg-sort-pre') || document.getElementById('msg-sort-mode'))?.value || 'rank');

  let filtered = [...S.conversations];

  if (searchVal) {
    filtered = filtered.filter(c =>
      c.participant.toLowerCase().includes(searchVal) ||
      (c.textBlob || '').includes(searchVal)
    );
  }

  // Filtrado reactivo por la tarjeta KPI seleccionada
  if (activeMessageCategoryFilter) {
    const SENT_INTERES  = '\uD83D\uDFE2 Inter\u00e9s Alto / Dispuesto a Demo';
    const SENT_CURIOSI  = '\uD83D\uDFE1 Curiosidad / Evaluando';
    const SENT_OBJEC    = '\uD83D\uDD34 Objeci\u00f3n / Rechazo Abierto';
    const SENT_FANTASMA = 'Fantasma / Ignorado';
    const INT_CALIDO    = 'Lead C\u00e1lido / Oportunidad Real';
    const INT_CUALIF    = 'Cualificaci\u00f3n en Proceso';
    const INT_SOCIAL    = 'Conversaci\u00f3n Social';
    const INT_NOINTER   = 'No Interesado / Cerrado';

    filtered = filtered.filter(c => {
      if (activeMessageCategoryFilter === 'high_interest') return c.sentiment === SENT_INTERES || c.intent === INT_CALIDO || c.intent === INT_CUALIF || c.sentiment === 'positive' || c.sentiment === 'high_interest';
      if (activeMessageCategoryFilter === 'friendly') return c.is_friendly || c.intent === INT_SOCIAL || c.sentiment === 'friendly';
      if (activeMessageCategoryFilter === 'inbound') return c.is_they_selling;
      if (activeMessageCategoryFilter === 'curiosity') return c.sentiment === SENT_CURIOSI || c.sentiment === 'curiosity';
      if (activeMessageCategoryFilter === 'ghosted') return c.sentiment === SENT_FANTASMA || c.sentiment === 'ghosted';
      if (activeMessageCategoryFilter === 'rejection') return c.sentiment === SENT_OBJEC || c.intent === INT_NOINTER || c.sentiment === 'rejection';
      return true;
    });
  } else if (sentimentFilter) {
    filtered = filtered.filter(c => c.sentiment === sentimentFilter);
  }

  if (sortMode === 'turns') {
    filtered.sort((a, b) => b.turns - a.turns);
  } else if (sortMode === 'recent') {
    filtered.sort((a, b) => b.lastDate.localeCompare(a.lastDate));
  } else {
    const rank = { positive: 0, high_interest: 0, curiosity: 1, friendly: 2, ghosted: 3, rejection: 4 };
    filtered.sort((a, b) => (rank[a.sentiment] ?? 5) - (rank[b.sentiment] ?? 5));
  }

  const sentimentLabel = {
    positive:     { badge: '🟢 Interés Alto',    color: 'var(--green)' },
    high_interest:{ badge: '🟢 Interés Alto',    color: 'var(--green)' },
    ghosted:      { badge: '👻 Sin Respuesta',   color: 'var(--muted)' },
    rejection:    { badge: '🔴 Rechazo',         color: 'var(--red)' },
    curiosity:    { badge: '🟡 Curiosidad',      color: '#f59e0b' },
    friendly:     { badge: '🤝 Social',          color: '#3b82f6' },
  };

  if (!filtered.length) {
    container.innerHTML = `<div class="no-results" style="padding:20px; text-align:center; color:var(--muted);">No hay conversaciones que coincidan con los filtros seleccionados. ${activeMessageCategoryFilter ? '<button class="mini-btn" style="margin-left:8px;" onclick="setMessagesCategoryFilter(null)">Ver Todas</button>' : ''}</div>`;
    return;
  }

  container.innerHTML = filtered.slice(0, 50).map(c => {
    const sl = sentimentLabel[c.sentiment] || { badge: '💬 Conversación', color: 'var(--border2)' };
    const preview = c.last_msg_snippet || (c.msgs && c.msgs[0] && c.msgs[0].content) || '—';
    const cleanPreview = preview.length > 130 ? preview.slice(0, 130) + '...' : preview;
    const contact = S.contacts.find(ct => String(ct.id) === String(c.id));
    const isExpanded = S.expandedChats && S.expandedChats.has(c.id);

    return `
      <div class="kpi-card" style="margin-bottom:8px; display:flex; flex-direction:column; gap:8px; border-left:4px solid ${sl.color}">
        <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:6px;">
          <div style="font-weight:700; font-size:12px; color:var(--text); display:flex; align-items:center; gap:6px;">
            👤 ${getDisplayName({name: c.participant})}
            ${c.is_they_selling ? '<span class="badge" style="font-size:8px; background:rgba(236,72,153,0.15); color:#f472b6; border:1px solid rgba(236,72,153,0.3)">📥 Inbound Pitch</span>' : ''}
            ${c.is_friendly ? '<span class="badge" style="font-size:8px; background:rgba(59,130,246,0.15); color:#60a5fa; border:1px solid rgba(59,130,246,0.3)">🤝 Social</span>' : ''}
          </div>
          <div style="display:flex; align-items:center; gap:6px;">
            <span class="badge" style="font-size:9px; color:${sl.color}; background:rgba(0,0,0,0.1)">${sl.badge}</span>
            <span style="font-size:10px; color:var(--muted); font-family:'JetBrains Mono',monospace;">${c.turns} msg${c.turns !== 1 ? 's' : ''}</span>
            ${c.lastDate ? `<span style="font-size:9px; color:var(--muted);">${c.lastDate.slice(0,10)}</span>` : ''}
            <button class="mini-btn" onclick="toggleChatExpand('${c.id}')" style="font-size:10px; padding:3px 8px;">
              ${isExpanded ? '▲ Ocultar chat' : '▼ Ver chat completo'}
            </button>
          </div>
        </div>

        <div style="font-size:11px; color:var(--muted2); line-height:1.5; font-style:italic; background:var(--bg); padding:6px 10px; border-radius:6px; border:1px solid var(--border);">
          "${cleanPreview}"
        </div>

        <!-- HILO DE CHAT COMPLETO DESPLEGADO IN-PLACE -->
        ${isExpanded ? `
          <div class="chat-history-container" style="margin-top:4px; border-top:1px solid var(--border); padding-top:10px; display:flex; flex-direction:column; gap:10px; max-height:350px; overflow-y:auto; padding-right:4px;">
            ${(c.msgs && c.msgs.length > 0) ? c.msgs.map(m => {
              const me = S.isMe(m.sender);
              const align = me ? 'flex-end' : 'flex-start';
              const bg = me ? 'rgba(59,130,246,0.12)' : 'var(--bg)';
              const borderCol = me ? 'rgba(59,130,246,0.3)' : 'var(--border)';
              const senderColor = me ? '#60a5fa' : 'var(--purple)';

              return `
                <div style="align-self:${align}; max-width:85%; background:${bg}; border:1px solid ${borderCol}; border-radius:10px; padding:8px 12px; font-size:11px;">
                  <div style="font-size:9px; font-weight:700; color:${senderColor}; margin-bottom:4px; display:flex; justify-content:space-between; gap:12px;">
                    <span>${m.sender}</span>
                    <span>${m.date ? m.date.slice(0, 16) : ''}</span>
                  </div>
                  <div style="line-height:1.5; color:var(--text); white-space:pre-wrap;">${m.content}</div>
                </div>
              `;
            }).join('') : `
              <div style="background:var(--bg); padding:10px; border-radius:8px; border:1px solid var(--border); font-size:11px; color:var(--text-muted);">
                <div style="font-weight:700; color:var(--text); margin-bottom:4px;">💬 Snippet de Conversación Registrada:</div>
                <div style="font-style:italic;">"${c.last_msg_snippet || 'Sin fragmento disponible.'}"</div>
              </div>
            `}

            <!-- ACCIONES RÁPIDAS DE RESPUESTA EN 1-CLIC -->
            <div style="display:flex; gap:8px; margin-top:8px; padding-top:8px; border-top:1px dashed var(--border);">
              ${contact ? `
                <button class="mini-btn primary" onclick="openModal(${contact.id})" style="flex:1; font-weight:700; font-size:11px; padding:6px; background:linear-gradient(135deg, var(--accent), var(--purple)); border:none; color:white;">
                  💬 Responder / Redactar Pitch con IA
                </button>
                <button class="mini-btn" onclick="viewContactInNetwork(${contact.id})" style="flex:1; font-weight:600; font-size:11px; padding:6px;">
                  👤 Ver Perfil Completo en Mi Red
                </button>
              ` : `
                <button class="mini-btn" style="flex:1; font-size:10px;" disabled>Contacto no indexado en red actual</button>
              `}
            </div>
          </div>
        ` : ''}
      </div>
    `;
  }).join('');
}


function openModal(id) {
  const c = S.contacts.find(c => c.id === id);
  if (!c) return;
  S.pitchLead = c;
  S.pitchApproach = 'directo';

  // Rellenar campos del CRM & Edición
  document.getElementById('modal-crm-name-input').value = getDisplayName(c);
  document.getElementById('modal-crm-pos-input').value = c.customPosition || c.position || '';
  document.getElementById('modal-crm-comp-input').value = getDisplayCompany(c);
  document.getElementById('modal-crm-status').value = c.crmStatus || 'Ninguno';
  document.getElementById('modal-crm-notes').value = c.crmNotes || '';

  const dateWrap = document.getElementById('modal-crm-date-wrap');
  const dateSpan = document.getElementById('modal-crm-date');
  if (c.crmDate) {
    dateSpan.textContent = c.crmDate;
    dateWrap.style.display = 'block';
  } else {
    dateWrap.style.display = 'none';
  }

  // Mostrar u ocultar botón de chat
  const chatBtn = document.getElementById('modal-crm-chat-btn');
  const nameNorm = norm(c.name);
  const hasChat = S.messages && S.messages.length > 0 && S.conversations && S.conversations.some(conv => 
    norm(conv.participant).includes(nameNorm)
  );
  if (hasChat) {
    chatBtn.style.display = 'inline-flex';
  } else {
    chatBtn.style.display = 'none';
  }

  onModalDataChange(); // verificar indicador de modificado

  syncCrmPills(c.crmStatus || 'Ninguno'); // resaltar pill activo
  updatePitchModal();
  document.getElementById('pitch-modal').classList.add('open');
}

function closeModal() { document.getElementById('pitch-modal').classList.remove('open'); }
document.getElementById('pitch-modal').addEventListener('click', e => { if (e.target === e.currentTarget) closeModal(); });

// ═══════════════════════════════════════════════════════════════════════
// ANALÍTICA AVANZADA (RevOps)
// ═══════════════════════════════════════════════════════════════════════
let analyticsChartInstance = null;

function renderAnalytics() {
  if (!S.loadedParts.messages) {
    document.getElementById('analytics-locked').style.display = 'block';
    document.getElementById('analytics-dashboard').style.display = 'none';
    return;
  }
  
  document.getElementById('analytics-locked').style.display = 'none';
  document.getElementById('analytics-dashboard').style.display = 'block';

  const conversations = Object.values(S.threads);
  if (conversations.length === 0) return;

  // Analizar últimos 30 días
  const now = new Date();
  const thirtyDaysAgo = new Date();
  thirtyDaysAgo.setDate(now.getDate() - 30);

  let sentMessages = 0;
  let respondedThreads = 0;
  let totalVelocityDays = 0;
  let velocityCount = 0;
  let avgEgoScore = 0; // We'll mock this for now since it needs LLM

  const dailyStats = {};
  for(let i=0; i<30; i++) {
    const d = new Date();
    d.setDate(now.getDate() - i);
    const dateStr = d.toISOString().split('T')[0];
    dailyStats[dateStr] = { sent: 0, received: 0 };
  }

  const recentActivity = [];

  conversations.forEach(thread => {
    let hasSent = false;
    let hasReceived = false;
    let firstSentDate = null;
    let firstReceivedDate = null;

    thread.messages.forEach(msg => {
      const msgDate = new Date(msg.DATE);
      if (msgDate >= thirtyDaysAgo) {
        const dateStr = msgDate.toISOString().split('T')[0];
        
        if (msg.FROM === S.userName) {
          sentMessages++;
          hasSent = true;
          if (dailyStats[dateStr]) dailyStats[dateStr].sent++;
          
          if (!firstSentDate || msgDate < firstSentDate) firstSentDate = msgDate;
          
          // Add to recent activity
          if (recentActivity.length < 20) {
            recentActivity.push({
              date: msgDate,
              type: 'sent',
              text: `Mensaje enviado a ${thread.senderName || 'Desconocido'}`
            });
          }
        } else {
          hasReceived = true;
          if (dailyStats[dateStr]) dailyStats[dateStr].received++;
          
          if (!firstReceivedDate || msgDate < firstReceivedDate) firstReceivedDate = msgDate;
          
          if (recentActivity.length < 20) {
            recentActivity.push({
              date: msgDate,
              type: 'received',
              text: `Respuesta recibida de ${thread.senderName || 'Desconocido'}`
            });
          }
        }
      }
    });

    if (hasSent && hasReceived) {
      respondedThreads++;
    }

    if (firstSentDate && firstReceivedDate && firstReceivedDate > firstSentDate) {
      const diffTime = Math.abs(firstReceivedDate - firstSentDate);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      totalVelocityDays += diffDays;
      velocityCount++;
    }
  });

  // Calculate KPIs
  const replyRate = sentMessages > 0 ? ((respondedThreads / sentMessages) * 100).toFixed(1) : 0;
  const velocity = velocityCount > 0 ? (totalVelocityDays / velocityCount).toFixed(1) : '--';
  
  // Set KPI DOM
  document.getElementById('ana-kpi-sent').innerText = sentMessages;
  document.getElementById('ana-kpi-reply').innerText = `${replyRate}%`;
  document.getElementById('ana-kpi-velocity').innerText = velocity !== '--' ? `${velocity}d` : '--';
  document.getElementById('ana-kpi-ego').innerText = '8.2/10'; // Mock ego score for UI demo

  // Render Timeline
  recentActivity.sort((a, b) => b.date - a.date);
  const timelineEl = document.getElementById('analytics-timeline');
  timelineEl.innerHTML = '';
  
  if (recentActivity.length === 0) {
    timelineEl.innerHTML = '<div style="font-size:12px; color:var(--muted);">No hay actividad en los últimos 30 días.</div>';
  } else {
    recentActivity.slice(0, 8).forEach(act => {
      const dateStr = act.date.toLocaleDateString() + ' ' + act.date.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
      const color = act.type === 'sent' ? 'var(--accent)' : 'var(--green)';
      const icon = act.type === 'sent' ? '📤' : '📥';
      
      const el = document.createElement('div');
      el.style.cssText = `display:flex; align-items:flex-start; gap:10px; font-size:12px; border-left:2px solid ${color}; padding-left:10px; background:var(--surface); padding:8px 10px; border-radius:0 8px 8px 0;`;
      el.innerHTML = `
        <div style="font-size:14px;">${icon}</div>
        <div>
          <div style="color:var(--text); font-weight:500;">${act.text}</div>
          <div style="color:var(--muted); font-size:10px; margin-top:3px; font-family:'JetBrains Mono', monospace;">${dateStr}</div>
        </div>
      `;
      timelineEl.appendChild(el);
    });
  }

  // Render Chart
  const labels = [];
  const sentData = [];
  const receivedData = [];
  
  // Reverse to show chronological order
  const sortedDates = Object.keys(dailyStats).sort();
  
  sortedDates.forEach(date => {
    // Format date as DD/MM
    const [, month, day] = date.split('-');
    labels.push(`${day}/${month}`);
    sentData.push(dailyStats[date].sent);
    receivedData.push(dailyStats[date].received);
  });

  const ctx = document.getElementById('chart-analytics').getContext('2d');
  
  if (analyticsChartInstance) {
    analyticsChartInstance.destroy();
  }

  const textColor = getComputedStyle(document.body).getPropertyValue('--text-muted').trim();
  const gridColor = getComputedStyle(document.body).getPropertyValue('--border').trim();

  analyticsChartInstance = new Chart(ctx, {
    type: 'bar',
    data: {
      labels: labels,
      datasets: [
        {
          label: 'Enviados',
          data: sentData,
          backgroundColor: '#4f46e5',
          borderRadius: 4,
          barPercentage: 0.6,
          categoryPercentage: 0.8
        },
        {
          label: 'Respuestas Recibidas',
          data: receivedData,
          backgroundColor: '#10b981',
          borderRadius: 4,
          barPercentage: 0.6,
          categoryPercentage: 0.8
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: { labels: { color: textColor, font: { family: 'Inter', size: 11 } } },
        tooltip: { mode: 'index', intersect: false }
      },
      scales: {
        x: { 
          grid: { color: gridColor, drawBorder: false },
          ticks: { color: textColor, font: { family: 'JetBrains Mono', size: 9 }, maxTicksLimit: 15 }
        },
        y: {
          grid: { color: gridColor, drawBorder: false },
          ticks: { color: textColor, font: { family: 'JetBrains Mono', size: 10 } },
          beginAtZero: true
        }
      },
      interaction: { mode: 'nearest', axis: 'x', intersect: false }
    }
  });
}

// Resalta el pill CRM activo en el modal
function syncCrmPills(status) {
  const statuses = ['Lead','Pitch','Conversacion','Reunion','Cerrado','Descartado'];
  statuses.forEach(s => {
    const btn = document.getElementById('qbtn-' + s);
    if (!btn) return;
    btn.className = 'crm-qbtn' + (s === status ? ' active-' + s : '');
  });
}

// Click rápido en un pill del modal → guarda estado + actualiza Kanban
function quickSetCrm(status) {
  const c = S.pitchLead;
  if (!c) return;
  // Actualizar select oculto para mantener consistencia con saveModalCrm
  const sel = document.getElementById('modal-crm-status');
  if (sel) sel.value = status;
  // Guardar directamente
  saveContactCrm(c.id, status, c.crmNotes || '', null);
  syncCrmPills(status);
  // Feedback visual en el pill
  const btn = document.getElementById('qbtn-' + status);
  if (btn) {
    const orig = btn.textContent;
    btn.textContent = '✓ Guardado';
    setTimeout(() => { btn.textContent = orig; }, 1200);
  }
}

