function updateSim() {
  const slider = document.getElementById('sim-conn-slider');
  const connValEl = document.getElementById('sim-conn-val');
  const deadEl = document.getElementById('sim-dead');
  const reachEl = document.getElementById('sim-reach');
  const dunbarEl = document.getElementById('sim-dunbar');
  
  if (!slider) return;
  const conn = parseInt(slider.value);
  connValEl.textContent = conn.toLocaleString();
  
  // 50% dead weight on average
  const dead = Math.round(conn * 0.5);
  deadEl.textContent = dead.toLocaleString();
  
  // 1% to 3% organic reach
  const rMin = Math.round(conn * 0.01);
  const rMax = Math.round(conn * 0.03);
  reachEl.textContent = `${rMin} - ${rMax}`;
  
  // Dunbar 150 target has 40% to 50% high engagement reach
  // 150 * 0.4 = 60, 150 * 0.5 = 75
  dunbarEl.textContent = "60 - 75";
}

