function scoreColorCrm(status) {
  const map = {
    'Lead': 'var(--accent)',
    'Pitch': 'var(--purple)',
    'Conversacion': 'var(--amber)',
    'Reunion': '#06b6d4',
    'Cerrado': 'var(--green)',
    'Descartado': 'var(--red)'
  };
  return map[status] || 'var(--muted)';
}

function renderCRM() {
  const board = document.getElementById('crm-kanban-board');
  const emptyState = document.getElementById('crm-empty-state');
  if (!board) return;
  try {

  // Si no hay ZIP cargado pero sí hay CRM en localStorage, reconstruir desde ahí
  let crmContacts;
  if (S.contacts.length === 0) {
    const raw = localStorage.getItem('radar_comercial_crm');
    if (raw) {
      try {
        const db = JSON.parse(raw);
        crmContacts = Object.entries(db)
          .filter(([, v]) => v.status && v.status !== 'Ninguno')
          .map(([key, v], i) => ({
            id: i,
            name: v.customName || key,
            company: v.customCompany || '—',
            position: v.customPosition || '—',
            country: '',
            sector: '',
            hierarchy: '',
            score: 0,
            crmStatus: v.status,
            crmNotes: v.notes || '',
            crmDate: v.date || '',
            email: '',
            url: ''
          }));
      } catch(e) { crmContacts = []; }
    } else {
      crmContacts = [];
    }
  } else {
    // Filtrar contactos con un estado de CRM activo
    crmContacts = S.contacts.filter(c => c.crmStatus && c.crmStatus !== 'Ninguno');
  }

  // Filtros de búsqueda
  const searchVal = norm(document.getElementById('crm-search').value);
  const minScore = parseInt(document.getElementById('crm-filter-score').value);

  if (searchVal) {
    crmContacts = crmContacts.filter(c => 
      norm(c.name).includes(searchVal) || 
      norm(c.company || '').includes(searchVal) || 
      norm(c.position || '').includes(searchVal) || 
      norm(c.crmNotes || '').includes(searchVal)
    );
  }

  if (minScore > 0) {
    crmContacts = crmContacts.filter(c => c.score >= minScore);
  }

  // KPIs — usamos crmContacts (ya cargados desde localStorage o S.contacts)
  // para que funcionen tanto con ZIP como sin él
  const allCrmEntries = S.contacts.length > 0
    ? S.contacts.filter(c => c.crmStatus && c.crmStatus !== 'Ninguno')
    : crmContacts;

  const totalActive = allCrmEntries.filter(c => c.crmStatus !== 'Cerrado' && c.crmStatus !== 'Descartado').length;
  const totalConv = allCrmEntries.filter(c => c.crmStatus === 'Conversacion').length;
  const totalMeet = allCrmEntries.filter(c => c.crmStatus === 'Reunion').length;
  const totalWon = allCrmEntries.filter(c => c.crmStatus === 'Cerrado').length;
  const totalLead = allCrmEntries.filter(c => c.crmStatus === 'Lead').length;
  const totalPitch = allCrmEntries.filter(c => c.crmStatus === 'Pitch').length;
  
  // Pipeline Value Calculation (Business Impact)
  const bountyPerWin = 150;
  const pipeValue = (totalLead * 0.1 * bountyPerWin) + 
                    (totalPitch * 0.2 * bountyPerWin) + 
                    (totalConv * 0.4 * bountyPerWin) + 
                    (totalMeet * 0.8 * bountyPerWin) + 
                    (totalWon * 1.0 * bountyPerWin);
                    
  const activeCrmCount = allCrmEntries.filter(c => c.crmStatus !== 'Descartado').length;

  const elActive = document.getElementById('crm-kpi-active');
  const elConv   = document.getElementById('crm-kpi-conv');
  const elMeet   = document.getElementById('crm-kpi-meet');
  const elWon    = document.getElementById('crm-kpi-won');
  const elBounty = document.getElementById('crm-kpi-bounty');
  const elNbCrm  = document.getElementById('nb-crm');
  
  if (elActive) elActive.textContent = totalActive;
  if (elConv)   elConv.textContent   = totalConv;
  if (elMeet)   elMeet.textContent   = totalMeet;
  if (elWon)    elWon.textContent    = totalWon;
  if (elBounty) elBounty.textContent = '$' + pipeValue.toLocaleString('en-US', {minimumFractionDigits: 0, maximumFractionDigits: 0});
  if (elNbCrm)  elNbCrm.textContent  = activeCrmCount;

  board.style.display = 'grid';
  if (emptyState) emptyState.style.display = 'none';

  const columns = [
    { id: 'Lead', label: 'Por Contactar', color: 'var(--accent)' },
    { id: 'Pitch', label: 'Pitch Enviado', color: 'var(--purple)' },
    { id: 'Conversacion', label: 'En Conversación', color: 'var(--amber)' },
    { id: 'Reunion', label: 'Reunión / Demo', color: '#06b6d4' },
    { id: 'Cerrado', label: 'Cerrado / Ganado', color: 'var(--green)' },
    { id: 'Descartado', label: 'Descartado', color: 'var(--red)' }
  ];

  board.innerHTML = columns.map(col => {
    const colLeads = crmContacts.filter(c => c.crmStatus === col.id);
    return `
      <div class="crm-column">
        <div class="crm-column-header">
          <span class="crm-column-title" style="color:${col.color}">${col.label}</span>
          <span class="crm-column-count">${colLeads.length}</span>
        </div>
        <div style="display:flex; flex-direction:column; gap:8px; overflow-y:auto; max-height:500px; padding-right:2px;">
          ${colLeads.map(c => `
            <div class="crm-card" onclick="openModal(${c.id})">
              <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:4px;">
                <div class="crm-card-name" title="${c.name}">${c.name}</div>
                <div style="font-size:8px; font-family:'JetBrains Mono',monospace; padding:1px 3px; border-radius:4px; background:rgba(255,255,255,0.05); color:${scoreColor(c.score)}; flex-shrink:0;">
                  ${c.score}
                </div>
              </div>
              <div class="crm-card-meta">
                <div style="font-weight:600; color:var(--text); text-overflow:ellipsis; overflow:hidden; white-space:nowrap;" title="${c.company}">${c.company || '—'}</div>
                <div style="color:var(--muted2); text-overflow:ellipsis; overflow:hidden; white-space:nowrap; font-size:9px;" title="${c.position}">${c.position || '—'}</div>
              </div>
              ${c.crmNotes ? `
                <div class="crm-card-notes" title="${c.crmNotes}">${c.crmNotes}</div>
              ` : ''}
              <div style="display:flex; justify-content:space-between; align-items:center; margin-top:4px; border-top:1px solid var(--border); padding-top:6px; gap:4px;">
                <span style="font-size:8px; color:var(--muted); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:80px;">${countryFlag(c.country || '')}</span>
                <div onclick="event.stopPropagation();">
                  <select class="filter-input" style="font-size:8px; padding:1px 3px; border-radius:4px; height:auto; background:var(--surface); border-color:var(--border);" onchange="saveContactCrm(${c.id}, this.value)">
                    <option value="Lead" ${c.crmStatus === 'Lead' ? 'selected' : ''}>Lead</option>
                    <option value="Pitch" ${c.crmStatus === 'Pitch' ? 'selected' : ''}>Pitch</option>
                    <option value="Conversacion" ${c.crmStatus === 'Conversacion' ? 'selected' : ''}>Conv</option>
                    <option value="Reunion" ${c.crmStatus === 'Reunion' ? 'selected' : ''}>Demo</option>
                    <option value="Cerrado" ${c.crmStatus === 'Cerrado' ? 'selected' : ''}>Ganado</option>
                    <option value="Descartado" ${c.crmStatus === 'Descartado' ? 'selected' : ''}>Desc</option>
                    <option value="Ninguno">Eliminar</option>
                  </select>
                </div>
              </div>
            </div>
          `).join('')}
          ${colLeads.length === 0 ? `
            <div style="font-size:9px; color:var(--muted); text-align:center; padding:16px; border:1px dashed var(--border); border-radius:8px;">Sin contactos<br><br><button onclick="loadDemoData()" style="pointer-events:auto; background:var(--bg); border:1px solid var(--accent); color:var(--accent); padding:4px 8px; border-radius:4px; cursor:pointer; font-size:9px; font-weight:600; transition:all 0.15s;" onmouseover="this.style.background='var(--accent)'; this.style.color='var(--bg)'" onmouseout="this.style.background='var(--bg)'; this.style.color='var(--accent)'">Inyectar Demo</button></div>
          ` : ''}
        </div>
      </div>
    `;
  }).join('');
  } catch(err) {
    console.error('[renderCRM ERROR]', err);
    board.innerHTML = `<div style="grid-column:1/-1; padding:24px; text-align:center; color:var(--red); font-family:'JetBrains Mono',monospace; font-size:11px;">⚠️ Error al renderizar el pipeline: ${err.message}<br><small style='opacity:.6'>Abre la consola del navegador (F12) para ver el detalle completo.</small></div>`;
    board.style.display = 'grid';
    if (emptyState) emptyState.style.display = 'none';
  }
}

function exportCrmCSV() {
  const crmLeads = S.contacts.filter(c => c.crmStatus && c.crmStatus !== 'Ninguno');
  if (!crmLeads.length) { alert('No hay leads en el CRM para exportar.'); return; }
  
  const fields = ['name','company','position','country','sector','hierarchy','score','crmStatus','crmNotes','crmDate','email','url'];
  const rows = [fields.join(',')];
  crmLeads.forEach(c => rows.push(fields.map(f => `"${String(c[f]||'').replace(/"/g,'""')}"`).join(',')));
  downloadFile(rows.join('\n'), `radar_crm_pipeline_${new Date().toISOString().slice(0,10)}.csv`, 'text/csv;charset=utf-8;');
}

function clearCRMData() {
  if (confirm("⚠️ ¿Estás seguro de que deseas vaciar todo tu CRM local? Esto eliminará todos los estados y notas guardadas permanentemente de tu navegador.")) {
    localStorage.removeItem('radar_comercial_crm');
    S.contacts.forEach(c => {
      c.crmStatus = 'Ninguno';
      c.crmNotes = '';
      c.crmDate = '';
      c.customName = '';
      c.customPosition = '';
      c.customCompany = '';
    });
    finalize();
    alert("CRM limpiado con éxito.");
  }
}

function exportCrmBackup() {
  const raw = localStorage.getItem('radar_comercial_crm');
  if (!raw || raw === '{}') {
    alert("El CRM está vacío, no hay nada que respaldar.");
    return;
  }
  downloadFile(raw, `radar_crm_backup_${new Date().toISOString().slice(0,10)}.json`, 'application/json;charset=utf-8;');
}

function importCrmBackup(input) {
  const file = input.files[0];
  if (!file) return;
  
  const reader = new FileReader();
  reader.onload = function(e) {
    try {
      const data = JSON.parse(e.target.result);
      if (typeof data !== 'object' || data === null) {
        throw new Error("El archivo no tiene el formato de copia de seguridad correcto.");
      }
      
      // Guardar en localStorage
      localStorage.setItem('radar_comercial_crm', JSON.stringify(data));
      
      // Recargar datos en memoria y re-renderizar
      finalize();
      
      alert("🎉 Copia de seguridad del CRM restaurada con éxito.");
    } catch (err) {
      alert("❌ Error al restaurar la copia de seguridad: " + err.message);
    }
    input.value = ''; // Reset input
  };
  reader.readAsText(file);
}

