function getAiResultFromCache(convId, participantName) {
  try {
    const raw = localStorage.getItem('radar_ai_cache');
    if (!raw) return null;
    const cache = JSON.parse(raw);
    if (cache[convId]) return cache[convId];
    if (participantName) {
      const key = norm(participantName);
      if (cache[key]) return cache[key];
    }
  } catch(e) {}
  return null;
}

function saveAiResultToCache(convId, result, participantName) {
  try {
    const raw = localStorage.getItem('radar_ai_cache');
    let cache = raw ? JSON.parse(raw) : {};
    cache[convId] = result;
    if (participantName) {
      cache[norm(participantName)] = result;
    }
    localStorage.setItem('radar_ai_cache', JSON.stringify(cache));
  } catch(e) {}
}

