// ────────────────────────────────────────────────────────────────────────
// SUPABASE AUTHENTICATION LOGIC
// ────────────────────────────────────────────────────────────────────────
let currentUser = null;

async function checkAuth() {
  const { data: { session } } = await supabase.auth.getSession();
  if (session) {
    currentUser = session.user;
    document.getElementById('supabase-auth-modal').style.display = 'none';
    
    // Add logout button to header if not exists
    if (!document.getElementById('logout-btn')) {
      const headerBtns = document.querySelector('.header-right');
      if (headerBtns) {
        const logoutBtn = document.createElement('button');
        logoutBtn.id = 'logout-btn';
        logoutBtn.className = 'btn btn-outline';
        logoutBtn.style.marginLeft = '10px';
        logoutBtn.innerHTML = 'Cerrar Sesión';
        logoutBtn.onclick = handleSupabaseLogout;
        headerBtns.appendChild(logoutBtn);
      }
    }
    await loadDataFromSupabase();
  } else {
    document.getElementById('supabase-auth-modal').style.display = 'flex';
  }
}

async function handleSupabaseLogin() {
  const email = document.getElementById('auth-email').value;
  const password = document.getElementById('auth-password').value;
  const { data, error } = await supabase.auth.signInWithPassword({ email, password });
  if (error) {
    document.getElementById('auth-error').textContent = error.message;
    document.getElementById('auth-error').style.display = 'block';
  } else {
    checkAuth();
  }
}

async function handleSupabaseRegister() {
  const email = document.getElementById('auth-email').value;
  const password = document.getElementById('auth-password').value;
  const { data, error } = await supabase.auth.signUp({ email, password });
  if (error) {
    document.getElementById('auth-error').textContent = error.message;
    document.getElementById('auth-error').style.display = 'block';
  } else {
    alert("Registro exitoso. Si el correo requiere confirmación, revisa tu bandeja de entrada.");
    checkAuth();
  }
}

async function handleSupabaseLogout() {
  await supabase.auth.signOut();
  location.reload();
}

async function loadDataFromSupabase() {
  console.log("Loading data from supabase for user:", currentUser.id);
  
  let allData = [];
  let from = 0;
  const step = 1000;
  let keepFetching = true;

  while (keepFetching) {
    const { data, error } = await supabase.from('contacts')
      .select('*')
      .order('created_at', { ascending: false })
      .range(from, from + step - 1);
      
    if (error) {
      console.error("Error fetching contacts:", error);
      break;
    }
    
    if (data && data.length > 0) {
      allData = allData.concat(data);
      from += step;
      if (data.length < step) keepFetching = false;
    } else {
      keepFetching = false;
    }
  }

  const data = allData;
  if (data && data.length > 0) {
    console.log(`Loaded ${data.length} contacts from Supabase`);
    // Map db rows to our local S.contacts format
    S.contacts = data.map(row => {
      const c = {
        id: row.contact_id,
        name: `${row.first_name || ''} ${row.last_name || ''}`.trim(),
        company: row.company,
        position: row.position,
        connected_on: row.connected_on,
        email_address: row.email_address,
        profile_url: row.profile_url,
        // Map CRM fields directly
        crmStatus: row.crm_status,
        crmNotes: row.crm_notes,
        customName: row.custom_name,
        customCompany: row.custom_company,
        customPosition: row.custom_position,
        crmDate: row.crm_date,
        msg_count: row.msg_count,
        latest_message: row.latest_message
      };
      
      // Inject raw data back if exists
      if (row.raw_data) {
        Object.assign(c, row.raw_data);
      }
      
      return c;
    });
    
    // Auto navigation to Mi Red
    S.loadedParts.connections = true;
    updateStatus();
    finalize();
    switchTab('network');
  }
}

