function updateCostCalculator(n) {
  const disp = document.getElementById('calc-count-display');
  const hEl = document.getElementById('calc-harvest-cost');
  const aEl = document.getElementById('calc-apify-cost');
  const iaEl = document.getElementById('calc-ia-cost');
  const totEl = document.getElementById('calc-total-cost');

  if (disp) disp.textContent = `${Number(n).toLocaleString()} contactos`;

  // Precios reales de mercado
  const harvestCost = (n * 0.005).toFixed(2); // ~$0.005 por perfil
  const apifyCost = Math.max(49, (n * 0.004)).toFixed(2); // ~$0.004 o Plan Base
  const iaCost = (Math.max(0.5, n * 0.00025)).toFixed(2); // OpenAI GPT-4o mini tokens
  const totalCost = (parseFloat(harvestCost) + parseFloat(iaCost)).toFixed(2);

  if (hEl) hEl.textContent = `$${harvestCost} USD`;
  if (aEl) aEl.textContent = `$${apifyCost} USD`;
  if (iaEl) iaEl.textContent = `~$${iaCost} USD`;
  if (totEl) totEl.textContent = `$${totalCost} USD`;
}

