async function generarPitchConQwenLive() {
  if (!S.pitchLead) return;
  const c = S.pitchLead;
  
  // UI active buttons
  document.querySelectorAll('.pitch-type-btn').forEach(b => b.classList.remove('active'));
  const qBtn = document.getElementById('pt-qwen');
  if (qBtn) qBtn.classList.add('active');

  const pitchEl = document.getElementById('modal-pitch-text');
  const thinkBox = document.getElementById('modal-qwen-thinking');
  const thinkText = document.getElementById('modal-qwen-thinking-text');
  const badge = document.getElementById('qwen-status-badge');

  if (thinkBox) thinkBox.style.display = 'block';
  if (thinkText) thinkText.textContent = 'Iniciando conexión con Qwen 3.8 (27B)...';
  if (badge) { badge.textContent = 'Pensando...'; badge.className = 'badge badge-purple'; }
  if (pitchEl) pitchEl.textContent = '⚡ Conectando con el copiloto de IA...';

  const leadName = c.customName || c.name || 'Colega';
  const leadPos = c.customPosition || c.position || 'Profesional';
  const leadComp = c.customCompany || c.company || 'su empresa';
  const leadCountry = c.country || 'México/Latam';
  const myCompany = (S.positions[0] && S.positions[0].company) || 'Radar Comercial';

  const postHook = c.last_post_text ? `\n- Gancho de conversación (Último post que publicó en LinkedIn): "${c.last_post_text.slice(0, 180)}..."` : '';
  const prompt = `Actúa como un estratega de ventas B2B y Relationship Intelligence de Radar Comercial.
Redacta un mensaje directo de LinkedIn (máximo 45 palabras, sin sonar a spam corporativo ni venta agresiva):
- Prospecto: ${leadName} (${leadPos} en ${leadComp}, ${leadCountry})${postHook}
- Puente cálido / Contexto compartido: Ambos compartimos red y conexiones en el ecosistema B2B/Fintech de México y Latam
- Propuesta de valor: Aceleración de cierres de cuentas enterprise mediante minería de relaciones cálidas de 1er grado
- Mi Empresa: ${myCompany}

Regla clave: Enfócate en abrir una conversación directa o pedir su opinión sobre el reto común sin rodeos. ${c.last_post_text ? 'Haz una breve alusión sutil y natural a su última publicación.' : ''}`;

  const provider = localStorage.getItem('radar_ai_provider') || 'qwen';
  const apiKey = localStorage.getItem('radar_ai_key') || '';
  const baseUrl = localStorage.getItem('radar_ai_base_url') || 'https://llm.disier.net/v1';
  const geminiKey = localStorage.getItem('radar_gemini_key') || (provider === 'gemini' ? apiKey : '');

  try {
    if (provider === 'qwen' && apiKey) {
      const response = await fetch(`${baseUrl}/chat/completions`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${apiKey}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          model: 'Qwen/Qwen3.8-27B',
          messages: [{ role: 'user', content: prompt }],
          max_tokens: 2500,
          temperature: 0.6,
          stream: true
        })
      });

      if (!response.ok) throw new Error(`Status ${response.status}`);

      const reader = response.body.getReader();
      const decoder = new TextDecoder('utf-8');
      let reasoningBuffer = '';
      let contentBuffer = '';

      if (pitchEl) pitchEl.textContent = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        const chunkStr = decoder.decode(value, { stream: true });
        const lines = chunkStr.split('\n');
        
        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const dataStr = line.slice(6).trim();
            if (dataStr === '[DONE]') break;
            try {
              const json = JSON.parse(dataStr);
              const delta = json.choices[0]?.delta || {};
              
              if (delta.reasoning_content) {
                reasoningBuffer += delta.reasoning_content;
                if (thinkText) {
                  thinkText.textContent = reasoningBuffer;
                  thinkBox.scrollTop = thinkBox.scrollHeight;
                }
              }
              
              if (delta.content) {
                if (badge) { badge.textContent = 'Redactando...'; badge.className = 'badge badge-green'; }
                contentBuffer += delta.content;
                if (pitchEl) pitchEl.textContent = contentBuffer.trimStart();
              }
            } catch (e) {}
          }
        }
      }

      if (contentBuffer.trim()) {
        if (badge) { badge.textContent = 'Listo (Qwen 3.8)'; badge.className = 'badge badge-green'; }
        return;
      }
    }
  } catch (err) {
    console.warn('[Qwen Streaming fallback to Gemini]', err);
  }

  // Fallback transparente a Gemini 2.5 Flash
  try {
    if (badge) { badge.textContent = 'Google Gemini 2.5 Flash'; badge.className = 'badge badge-amber'; }
    if (thinkText) thinkText.textContent = 'Conectando vía motor de respaldo de alta velocidad (Gemini 2.5 Flash)...';
    
    const url = `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${geminiKey}`;
    const res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: { maxOutputTokens: 300, temperature: 0.7 }
      })
    });
    
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    const txt = data.candidates[0]?.content?.parts[0]?.text || '';
    if (pitchEl) pitchEl.textContent = txt.trim();
    if (badge) { badge.textContent = 'Generado con Éxito'; badge.className = 'badge badge-green'; }
  } catch (e2) {
    if (pitchEl) pitchEl.textContent = `Hola ${leadName},\n\nAl coincidir en el ecosistema B2B, ¿cómo evalúan en ${leadComp} la minería de relaciones de 1er grado para acelerar cierres enterprise? Me gustaría conocer tu breve opinión.`;
    if (badge) { badge.textContent = 'Plantilla Heurística'; badge.className = 'badge badge-muted'; }
  }
}

