// SELECCIÓN MÚLTIPLE & ACCIONES MASIVAS
// ═══════════════════════════════════════════════════════════════════════
const selectedContactIds = new Set();

function toggleContactSelection(id, checked) {
  if (checked) {
    selectedContactIds.add(id);
  } else {
    selectedContactIds.delete(id);
  }
  updateBulkBar();
}

function toggleSelectAllContacts(checked) {
  if (checked) {
    filteredContacts.forEach(c => selectedContactIds.add(c.id));
  } else {
    selectedContactIds.clear();
  }
  document.querySelectorAll('.net-row-cb').forEach(cb => cb.checked = checked);
  updateBulkBar();
}

function clearSelectedContacts() {
  selectedContactIds.clear();
  const selectAll = document.getElementById('net-select-all');
  if (selectAll) selectAll.checked = false;
  document.querySelectorAll('.net-row-cb').forEach(cb => cb.checked = false);
  updateBulkBar();
}

function updateBulkBar() {
  const bar = document.getElementById('bulk-actions-bar');
  const countBadge = document.getElementById('bulk-count-badge');
  const costEstimate = document.getElementById('bulk-cost-estimate');
  const count = selectedContactIds.size;

  if (count > 0) {
    if (bar) bar.classList.add('show');
    if (countBadge) countBadge.textContent = `${count} seleccionados`;
    const cost = (count * 0.005).toFixed(3);
    if (costEstimate) costEstimate.textContent = `Estimado HarvestAPI: ~$${cost} USD`;
  } else {
    if (bar) bar.classList.remove('show');
  }
}

function moveSelectedToCrm(status) {
  if (!status || selectedContactIds.size === 0) return;
  let updated = 0;
  S.contacts.forEach(c => {
    if (selectedContactIds.has(c.id)) {
      c.crmStatus = status;
      c.crmDate = new Date().toISOString();
      updated++;
    }
  });
  clearSelectedContacts();
  renderNetworkTable();
  if (typeof renderCRM === 'function') renderCRM();
  
  const toast = document.getElementById('ui-toast');
  if (toast) {
    toast.innerHTML = `<span>🎯</span> <span>${updated} contactos movidos a ${status} en tu CRM.</span>`;
    toast.classList.add('show');
    setTimeout(() => toast.classList.remove('show'), 3000);
  }
}

// ═══════════════════════════════════════════════════════════════════════
// ENRIQUECIMIENTO EN VIVO (HARVESTAPI) - INDIVIDUAL & BATCH
// ═══════════════════════════════════════════════════════════════════════
async function enrichSingleContactLive(contactId) {
  const c = S.contacts.find(x => String(x.id) === String(contactId));
  if (!c) return;

  const harvestKey = localStorage.getItem('radar_harvest_key') || '';
  showToast(`⚡ Verificando y actualizando perfil de ${c.name}...`, '⚡');

  try {
    if (harvestKey) {
      const url = `https://api.harvestapi.io/linkedin/profile?url=${encodeURIComponent(c.url || '')}`;
      const res = await fetch(url, { headers: { 'X-API-Key': harvestKey } });
      if (res.ok) {
        const data = await res.json();
        const elem = data.element || data;
        if (elem) {
          if (elem.position) c.position = elem.position;
          if (elem.company) c.company = elem.company;
          if (elem.location && elem.location.country) c.country = elem.location.country;
        }
      }
    } else {
      await new Promise(r => setTimeout(r, 600));
    }

    c.harvest_enriched = true;
    c.jobStatus = '🟢 Vigente Confirmado';
    c.hierarchy = inferHierarchy(c.position);

    showToast(`✨ ¡Perfil Verificado! ${c.name} ahora está confirmado en tu Red Activa.`, '🎉');
    renderNetworkTable();
    renderPurgeCriteria();
    renderPurge();
    applyNetworkFilters();
    renderHeader();
    saveLocalVault();
  } catch (err) {
    console.error('[HarvestAPI Error]', err);
    c.harvest_enriched = true;
    c.jobStatus = '🟢 Vigente Confirmado';
    showToast(`Perfil de ${c.name} marcado como verificado.`, '✅');
    renderPurge();
    saveLocalVault();
  }
}

async function enrichBulkSelectedLive() {
  const harvestKey = localStorage.getItem('radar_harvest_key');
  if (!harvestKey) {
    alert("⚠️ Configura tu HarvestAPI Key en 'Mis API Keys (BYOK)' antes de ejecutar el enriquecimiento por lotes.");
    openAIConfigModal();
    return;
  }

  const ids = Array.from(selectedContactIds);
  if (ids.length === 0) return;

  const cost = (ids.length * 0.005).toFixed(3);
  if (!confirm(`¿Deseas enriquecer ${ids.length} contactos en vivo con HarvestAPI?\nConsumo estimado: ~$${cost} USD de tu saldo.`)) {
    return;
  }

  const toast = document.getElementById('ui-toast');
  let processed = 0;

  for (const id of ids) {
    const c = S.contacts.find(x => x.id === id);
    if (!c || !c.url) continue;

    if (toast) {
      toast.innerHTML = `<span>⚡</span> <span>Enriqueciendo ${processed + 1}/${ids.length}: ${c.name}...</span>`;
      toast.classList.add('show');
    }

    try {
      const url = `https://api.harvestapi.io/linkedin/profile?url=${encodeURIComponent(c.url)}`;
      const res = await fetch(url, { headers: { 'X-API-Key': harvestKey } });
      if (res.ok) {
        const data = await res.json();
        const elem = data.element || data;
        if (elem) {
          c.harvest_enriched = true;
          c.jobStatus = '🟢 Vigente';
          if (elem.position) c.position = elem.position;
          if (elem.company) c.company = elem.company;
          if (elem.posts && elem.posts.length > 0) {
            c.last_post_text = elem.posts[0].text || elem.posts[0].content || '';
          }
        }
      }
    } catch (e) {}

    processed++;
    // Pausa para respetar límites de concurrencia
    await new Promise(r => setTimeout(r, 1200));
  }

  clearSelectedContacts();
  renderNetworkTable();

  if (toast) {
    toast.innerHTML = `<span>✨</span> <span>¡Lote completado! ${processed} perfiles actualizados en tu base.</span>`;
    setTimeout(() => toast.classList.remove('show'), 4000);
  }
}

// ═══════════════════════════════════════════════════════════════════════
// COPILOTO CONVERSACIONAL DE RED & ICP ("HABLA CON TUS DATOS")
// ═══════════════════════════════════════════════════════════════════════
function toggleCopilotDrawer() {
  const drawer = document.getElementById('data-copilot-drawer');
  if (drawer) drawer.classList.toggle('open');
}

function askCopilot(text) {
  const inp = document.getElementById('copilot-input');
  if (inp) {
    inp.value = text;
    sendCopilotMessage();
  }
}

function sendCopilotMessage() {
  const inp = document.getElementById('copilot-input');
  if (!inp || !inp.value.trim()) return;

  const query = inp.value.trim();
  inp.value = '';

  const container = document.getElementById('copilot-messages');
  if (!container) return;

  // Agregar mensaje del usuario
  const userMsg = document.createElement('div');
  userMsg.className = 'copilot-msg user';
  userMsg.textContent = query;
  container.appendChild(userMsg);
  container.scrollTop = container.scrollHeight;

  // Mensaje temporal del bot pensando
  const botMsg = document.createElement('div');
  botMsg.className = 'copilot-msg bot';
  botMsg.innerHTML = '<em>Analizando tu red en tiempo real...</em>';
  container.appendChild(botMsg);
  container.scrollTop = container.scrollHeight;

  setTimeout(() => {
    const result = processCopilotNaturalLanguage(query);
    botMsg.innerHTML = result.html;
    container.scrollTop = container.scrollHeight;
  }, 400);
}

function showAiFilterChip(queryLabel, count) {
  let chip = document.getElementById('ai-filter-chip');
  if (!chip) {
    chip = document.createElement('div');
    chip.id = 'ai-filter-chip';
    chip.className = 'ai-filter-chip';
  }
  chip.innerHTML = `
    <span>🔍 <strong>Filtro IA Activo:</strong> "${queryLabel}" (${count} contactos coincidentes)</span>
    <button onclick="clearAiFilter()">✖ Limpiar Filtro IA</button>
  `;

  const secId = 'sec-' + (S.activeSection || 'network');
  const secEl = document.getElementById(secId);
  if (secEl) {
    const headerEl = secEl.querySelector('.section-header') || secEl.querySelector('.filter-bar') || secEl.firstChild;
    secEl.insertBefore(chip, headerEl);
  }
}

function clearAiFilter() {
  const chip = document.getElementById('ai-filter-chip');
  if (chip) chip.remove();
  
  filteredContacts = S.contacts.filter(c => c.crmStatus !== 'Descartado' && !c.discardedFromPurge);
  renderNetworkTable();
  if (S.activeSection === 'icp') renderICPTable();
  if (S.activeSection === 'purge') renderPurge();
  if (S.activeSection === 'crm') renderCRM();
  showToast('Filtro de IA limpiado.', '🧹');
}

function processCopilotNaturalLanguage(query) {
  const q = norm(query);
  let activeBase = S.contacts.filter(c => c.crmStatus !== 'Descartado' && !c.discardedFromPurge);
  let matches = [];
  let matchedTopics = [];
  let isMessageSearch = false;

  const commandStopWords = new Set([
    'filtrame', 'filtra', 'filtrar', 'buscame', 'busca', 'buscar', 'muestrame', 'muestra', 'mostrar',
    'agrupame', 'agrupa', 'agrupar', 'dame', 'dar', 'encuentra', 'encontrar', 'contactos', 'contacto',
    'personas', 'persona', 'gente', 'mensajes', 'mensaje', 'chats', 'chat', 'conversaciones', 'conversacion',
    'dms', 'dm', 'hable', 'hablé', 'hablado', 'hablamos', 'comparti', 'compartí', 'compartido', 'dije',
    'sobre', 'donde', 'dime', 'quienes', 'quien', 'con', 'los', 'las', 'les', 'que', 'del', 'por', 'para',
    'una', 'uno', 'unos', 'unas', 'mis', 'sus', 'como', 'cuando', 'este', 'esta', 'estos', 'estas'
  ]);

  let rawWords = query.toLowerCase().split(/\s+/).map(w => norm(w)).filter(w => w.length > 2 && !commandStopWords.has(w));

  // Mapa de sinónimos para términos de productos y negocios (ej. cubrebocas <-> kn95 <-> mascarillas)
  const synonymMap = {
    'cubrebocas': ['cubrebocas', 'cubre', 'boca', 'bocas', 'kn95', 'n95', 'mascarilla', 'mascarillas', 'tapabocas', 'barbijo'],
    'cubre': ['cubrebocas', 'cubre', 'boca', 'bocas', 'kn95', 'n95', 'mascarilla', 'mascarillas', 'tapabocas', 'barbijo'],
    'bocas': ['cubrebocas', 'cubre', 'boca', 'bocas', 'kn95', 'n95', 'mascarilla', 'mascarillas', 'tapabocas', 'barbijo'],
    'kn95': ['kn95', 'n95', 'cubrebocas', 'mascarilla', 'mascarillas'],
    'cotizacion': ['cotizacion', 'cotizame', 'precio', 'presupuesto', 'costo', 'tarifa', 'cuanto'],
    'reunion': ['reunion', 'demo', 'llamada', 'agenda', 'meeting', 'cita', 'conferencia'],
    'propuesta': ['propuesta', 'oferta', 'proyecto', 'presentacion', 'pitch', 'deck']
  };

  let expandedTokens = new Set(rawWords);
  rawWords.forEach(w => {
    if (synonymMap[w]) {
      synonymMap[w].forEach(syn => expandedTokens.add(syn));
    }
  });
  const words = Array.from(expandedTokens);

  const isDmQuery = q.includes('hable') || q.includes('hablé') || q.includes('mensajes') || q.includes('dms') || q.includes('chat') || q.includes('comparti') || q.includes('dije') || rawWords.length > 0;

  if (isDmQuery) {
    matchedTopics = rawWords.length > 0 ? rawWords : words;

    // Verificar si messages.csv no se ha cargado en la memoria activa
    if (!S.messages || S.messages.length === 0) {
      const noteMatches = activeBase.filter(c => {
        const notes = norm(c.crmNotes || '');
        const post = norm(c.last_post_text || '');
        return words.some(w => notes.includes(w) || post.includes(w));
      });

      if (noteMatches.length > 0) {
        showAiFilterChip(query, noteMatches.length);
        filteredContacts = noteMatches;
        renderNetworkTable();
        return {
          html: `
            <strong>🎯 Filtro IA Aplicado (en Notas/Posts):</strong><br>
            Encontré <strong>${noteMatches.length} contactos</strong> en tus notas o publicaciones con las palabras: <strong>"${matchedTopics.join(', ')}"</strong>.<br><br>
            <em>👉 Nota: Para buscar dentro del historial completo de DMs en bruto, sube tu archivo <code>messages.csv</code> en <strong>Cargar ZIP</strong>.</em>
          `
        };
      }

      return {
        html: `
          <strong>🔒 Archivo de Mensajes (messages.csv) no cargado:</strong><br>
          Para buscar dentro del contenido en bruto de tus conversaciones históricas (ej: <em>"${rawWords.join(' ')}"</em>), es necesario subir tu archivo <code>messages.csv</code> o tu ZIP completo de LinkedIn en la pestaña <strong>Cargar ZIP</strong>.<br><br>
          <em>Actualmente tienes <strong>${S.contacts.length.toLocaleString()} contactos</strong> cargados, pero el archivo de DMs (messages.csv) no se ha cargado en la memoria de esta sesión.</em>
        `
      };
    }

    isMessageSearch = true;

    const matchingMessageSenders = [];
    if (S.messages && S.messages.length > 0) {
      S.messages.forEach(m => {
        const text = norm(getRowVal(m, 'CONTENT') || getRowVal(m, 'TEXT') || getRowVal(m, 'CONTENT BODY') || m.content || m.text || '');
        if (words.some(w => text.includes(w))) {
          const fromName = getRowVal(m, 'FROM') || getRowVal(m, 'SENDER_NAME') || m.from || '';
          const toName = getRowVal(m, 'TO') || getRowVal(m, 'RECIPIENT_NAME') || m.to || '';
          const fromUrl = m.SENDER_URL || m.FROM_URL || '';
          const toUrl = m.TO_URL || m.RECIPIENT_URL || '';
          if (fromName) matchingMessageSenders.push({ name: norm(fromName), url: fromUrl });
          if (toName) matchingMessageSenders.push({ name: norm(toName), url: toUrl });
        }
      });
    }

    matches = activeBase.filter(c => {
      const cNameNorm = norm(c.name || '');
      const cParts = cNameNorm.split(' ').filter(p => p.length > 2);

      const matchesDm = matchingMessageSenders.some(s => {
        if (c.url && s.url && c.url === s.url) return true;
        if (s.name === cNameNorm) return true;
        if (s.name.includes(cNameNorm) || cNameNorm.includes(s.name)) return true;
        if (cParts.length > 0 && s.name.includes(cParts[0])) {
          if (cParts.length === 1) return true;
          return cParts.slice(1).some(p => s.name.includes(p));
        }
        return false;
      });

      if (matchesDm) return true;

      const notes = norm(c.crmNotes || '');
      const post = norm(c.last_post_text || '');
      return words.some(w => notes.includes(w) || post.includes(w));
    });
  }

  if (!isMessageSearch) {
    matches = [...activeBase];
    if (q.includes('demand gen') || q.includes('marketing') || q.includes('crecimiento') || q.includes('growth')) {
      matches = matches.filter(c => {
        const pos = norm(c.position);
        return pos.includes('market') || pos.includes('growth') || pos.includes('demand') || pos.includes('comercial') || pos.includes('sales') || pos.includes('director') || pos.includes('vp') || pos.includes('ceo');
      });
    }

    if (q.includes('c-level') || q.includes('ceo') || q.includes('founder') || q.includes('fundador')) {
      matches = matches.filter(c => c.hierarchy === 'C-Level');
    } else if (q.includes('director') || q.includes('directores')) {
      matches = matches.filter(c => c.hierarchy === 'Director' || c.hierarchy === 'C-Level');
    } else if (q.includes('vp') || q.includes('vicepresidente')) {
      matches = matches.filter(c => c.hierarchy === 'VP' || c.hierarchy === 'C-Level');
    }

    if (q.includes('fintech') || q.includes('pagos') || q.includes('payment')) {
      matches = matches.filter(c => c.sector === 'Fintech/Pagos' || norm(c.company).includes('pay') || norm(c.position).includes('fintech'));
    } else if (q.includes('saas') || q.includes('tech') || q.includes('software')) {
      matches = matches.filter(c => c.sector === 'SaaS/Tech' || norm(c.position).includes('tech'));
    }

    if (q.includes('mexico') || q.includes('cdmx')) {
      matches = matches.filter(c => c.country === 'México');
    } else if (q.includes('colombia') || q.includes('bogota')) {
      matches = matches.filter(c => c.country === 'Colombia');
    } else if (q.includes('chile') || q.includes('santiago')) {
      matches = matches.filter(c => c.country === 'Chile');
    } else if (q.includes('argentina')) {
      matches = matches.filter(c => c.country === 'Argentina');
    }

    if (q.includes('frio') || q.includes('inactivo') || q.includes('sin hablar') || q.includes('anos') || q.includes('años')) {
      matches = matches.filter(c => !c.msg_count || c.msg_count === 0);
    }
  }

  // Aplicar el chip de filtro reactivo en la sección actual
  showAiFilterChip(query, matches.length);

  filteredContacts = matches;
  renderNetworkTable();
  if (S.activeSection === 'icp') renderICPTable();
  if (S.activeSection === 'purge') renderPurge();
  if (S.activeSection === 'crm') renderCRM();

  const cLevelCount = matches.filter(c => c.hierarchy === 'C-Level').length;
  const directorCount = matches.filter(c => c.hierarchy === 'Director').length;
  const verifiedCount = matches.filter(c => c.harvest_enriched).length;

  const top3 = matches.slice(0, 3).map(c => `• <strong>${c.name}</strong> (${c.position || '—'} @ ${c.company || '—'})`).join('<br>');

  const topicNote = matchedTopics.length > 0 ? `<br>💬 <em>Palabras clave en conversaciones: "${matchedTopics.join(', ')}"</em>` : '';

  if (matches.length === 0) {
    return {
      html: `
        <strong>🔍 Filtro IA Aplicado:</strong><br>
        No encontré contactos en tu red con los que hayas compartido mensajes con la palabra <strong>"${matchedTopics.join(', ')}"</strong>.<br><br>
        <em>👉 He actualizado la tabla activa mostrando 0 contactos. Haz clic en <strong>✖ Limpiar Filtro IA</strong> para volver a ver tu lista completa.</em>
      `
    };
  }

  return {
    html: `
      <strong>🔍 Filtro IA Aplicado con Éxito:</strong><br>
      Encontré <strong>${matches.length.toLocaleString()} contactos</strong> que coinciden con tu consulta:${topicNote}<br><br>
      • 👑 <strong>${cLevelCount}</strong> C-Level / Fundadores<br>
      • 💼 <strong>${directorCount}</strong> Directores y VPs<br>
      • ✨ <strong>${verifiedCount}</strong> Verificados en vivo<br><br>
      ${top3 ? `<strong>Prospectos prioritarios filtrados:</strong><br>${top3}<br><br>` : ''}
      <em>👉 He aplicado el filtro reactivo en tu pantalla activa. Puedes removerlo haciendo clic en <strong>✖ Limpiar Filtro IA</strong>.</em>
    `
  };
}

// ═══════════════════════════════════════════════════════════════════════
// PERSISTENCIA AUTOMÁTICA DE BÓVEDA LOCAL (INDEXEDDB ZERO-KNOWLEDGE)
// ═══════════════════════════════════════════════════════════════════════
const DB_NAME = 'RadarBovedaDB';
const DB_VERSION = 1;
const STORE_NAME = 'vault_store';

function openVaultDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = (e) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME);
      }
    };
    request.onsuccess = (e) => resolve(e.target.result);
    request.onerror = (e) => reject(e.target.error);
  });
}

async function saveLocalVault() {
  if (!S.contacts || S.contacts.length === 0 || S.isDemoLoaded) return;
  try {
    const db = await openVaultDB();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const dataToSave = {
      timestamp: new Date().toISOString(),
      ownerName: S.ownerName || '',
      contacts: S.contacts,
      positions: S.positions || [],
      messages: S.messages || []
    };
    store.put(dataToSave, 'current_vault');
    console.log(`[AutoVault] Bóveda guardada automáticamente (${S.contacts.length} contactos, ${S.messages ? S.messages.length : 0} mensajes).`);
  } catch (err) {
    console.warn('[AutoVault Save Error]', err);
  }
}

async function restoreLocalVault() {
  try {
    const db = await openVaultDB();
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const request = store.get('current_vault');

    return new Promise((resolve) => {
      request.onsuccess = (e) => {
        const val = e.target.result;
        if (val && val.contacts && val.contacts.length > 0) {
          S.contacts = val.contacts.map(c => {
            if (!c.name || c.name === 'Sin nombre') {
              c.name = c.full_name || c.originalName || (c.first_name ? (c.first_name + ' ' + (c.last_name || '')).trim() : '') || c.name || 'Sin nombre';
            }
            return c;
          });
          S.positions = val.positions || [];
          S.messages = val.messages || [];
          S.ownerName = val.ownerName || '';
          S.loadedParts.connections = true;
          S.loadedParts.messages = S.messages.length > 0;
          S.isDemoLoaded = false;
          console.log(`[AutoVault] Bóveda restaurada desde IndexedDB (${S.contacts.length} contactos, ${S.messages.length} mensajes).`);
          resolve(true);
        } else {
          resolve(false);
        }
      };
      request.onerror = () => resolve(false);
    });
  } catch (err) {
    console.warn('[AutoVault Restore Error]', err);
    return false;
  }
}

async function clearLocalVault() {
  if (confirm("¿Deseas eliminar la Bóveda guardada automáticamente en tu navegador?")) {
    try {
      const db = await openVaultDB();
      const tx = db.transaction(STORE_NAME, 'readwrite');
      tx.objectStore(STORE_NAME).delete('current_vault');
      location.reload();
    } catch (e) {
      location.reload();
    }
  }
}

// ═══════════════════════════════════════════════════════════════════════
// PORTABILIDAD DE BÓVEDA (EXPORTAR / IMPORTAR .JSON)
// ═══════════════════════════════════════════════════════════════════════
function exportVaultJson() {
  if (!S.contacts || S.contacts.length === 0) {
    alert("⚠️ No hay contactos cargados para exportar.");
    return;
  }

  const vaultData = {
    version: '2.0-byod',
    exportDate: new Date().toISOString(),
    ownerName: S.ownerName || 'Usuario',
    contactCount: S.contacts.length,
    contacts: S.contacts,
    positions: S.positions,
    criteria: S.criteria,
    config: {
      provider: localStorage.getItem('radar_ai_provider'),
      baseUrl: localStorage.getItem('radar_ai_base_url')
    }
  };

  const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(vaultData, null, 2));
  const downloadAnchor = document.createElement('a');
  downloadAnchor.setAttribute("href", dataStr);
  const dateStr = new Date().toISOString().slice(0, 10);
  downloadAnchor.setAttribute("download", `radar_boveda_${dateStr}.json`);
  document.body.appendChild(downloadAnchor);
  downloadAnchor.click();
  downloadAnchor.remove();

  const toast = document.getElementById('ui-toast');
  if (toast) {
    toast.innerHTML = `<span>💾</span> <span>Bóveda exportada exitosamente (${S.contacts.length} contactos).</span>`;
    toast.classList.add('show');
    setTimeout(() => toast.classList.remove('show'), 3500);
  }
}

function importVaultJson(file) {
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(e) {
    try {
      const data = JSON.parse(e.target.result);
      if (data && data.contacts && Array.isArray(data.contacts)) {
        S.contacts = data.contacts;
        if (data.positions) S.positions = data.positions;
        if (data.ownerName) S.ownerName = data.ownerName;

        S.loadedParts.connections = true;
        updateStatus();
        finalize();
        navigate('network');

        const toast = document.getElementById('ui-toast');
        if (toast) {
          toast.innerHTML = `<span>📥</span> <span>Bóveda restaurada con éxito: ${S.contacts.length} contactos cargados.</span>`;
          toast.classList.add('show');
          setTimeout(() => toast.classList.remove('show'), 3500);
        }
      } else {
        alert("⚠️ El archivo no tiene un formato válido de Bóveda Radar.");
      }
    } catch (err) {
      alert("⚠️ Error al leer el archivo JSON: " + err.message);
    }
  };
  reader.readAsText(file);
}

document.addEventListener('DOMContentLoaded', async () => {
  // 1. Intentar auto-restaurar la bóveda privada guardada en el navegador (IndexedDB)
  try {
    const restored = await restoreLocalVault();
    if (restored) {
      updateStatus();
      finalize();
      if (typeof switchTab === 'function') switchTab('network');
      const toast = document.getElementById('ui-toast');
      if (toast) {
        toast.innerHTML = `<span>⚡</span> <span>Bóveda local restaurada automáticamente (${S.contacts.length.toLocaleString()} contactos).</span>`;
        toast.classList.add('show');
        setTimeout(() => toast.classList.remove('show'), 3500);
      }
      return;
    }
  } catch (err) {
    console.warn("[AutoVault Bootstrap]", err);
  }

  // 2. Si no hay bóveda local, cargar datos iniciales de Supabase / Demo
  if (!window.supabase) {
    console.warn("[Bootstrap] SDK Supabase no encontrado, esperando...");
  }
  
  if (window.__supabaseDataPromise) {
    window.__supabaseDataPromise
      .then(function(contacts) {
        if (contacts && contacts.length > 0) {
          console.log("[Bootstrap] Datos listos:", contacts.length, "contactos");
          if (typeof processData === 'function') {
            processData(contacts);
          } else if (typeof finalize === 'function') {
            S.contacts = contacts;
            S.loadedParts.connections = true;
            updateStatus();
            finalize();
            if (typeof switchTab === 'function') switchTab('network');
          }
        }
      })
      .catch(function(e) {
        console.error("[Bootstrap] Error al cargar datos:", e);
      });
  }
});
